INSERT OR REPLACE INTO cards (id, name, name_cn, name_jp, type, race, attribute, level, atk, def, desc_cn) VALUES
(99050989, 'Drillago', '钢钻龙', 'ドリラゴ', 'Effect Monster', 'Machine', 'DARK', 4, 1600, 1100, '对方场上只有表侧表示的攻击力1600以上的怪兽存在的场合，这张卡可以对对方玩家进行直接攻击。'),
(71218746, 'Drillroid', '钻头机人', 'ドリルロイド', 'Effect Monster', 'Machine', 'EARTH', 4, 1600, 1600, '①：这张卡向守备表示怪兽攻击的伤害计算前发动。那只怪兽破坏。'),
(93353691, 'Driven Daredevil', '不退的荒武者', '不退の荒武者', 'Synchro Monster', 'Warrior', 'EARTH', 7, 2400, 2100, '战士族调整＋调整以外的战士族怪兽1只以上 从持有比这张卡的攻击力高的攻击力的怪兽受到攻击的场合，这张卡不会被那次战斗破坏，进行战斗的对方怪兽在伤害计算后破坏。'),
(473469, 'Driving Snow', '猛吹雪', '猛吹雪', 'Trap Card', 'Normal', NULL, NULL, NULL, NULL, '自己的陷阱卡被对方控制的卡的效果破坏，从场地送去墓地时才能发动。场上的1张魔法·陷阱卡破坏。'),
(94145021, 'Droll & Lock Bird', '抽牌小丑与封锁鸟', 'ドロール＆ロックバード', 'Effect Monster', 'Spellcaster', 'WIND', 1, NULL, NULL, '①：自己·对方回合，对方在抽卡阶段以外从卡组把卡加入手卡的场合，把这张卡从手卡送去墓地才能发动。这个回合，双方不能从卡组把卡加入手卡。'),
(97973387, 'Droll Bird', '大嘴鸟', 'スピック', 'Normal Monster', 'Winged Beast', 'WIND', 2, 600, 500, '嘴巴非常大、大声的叫吓跑胆小的对方。'),
(16353197, 'Drooling Lizard', '鲜血吮吸者', '生き血をすするもの', 'Normal Monster', 'Reptile', 'EARTH', 3, 900, 800, '借着夜色袭击行人的人形吸血蛇。'),
(55773067, 'Drop Off', '打落', 'はたき落とし', 'Trap Card', 'Normal', NULL, NULL, NULL, NULL, '对方抽卡阶段时发动。对方的抽卡阶段抽的1张卡丢弃送去墓地。'),
(47475363, 'Drowning Mirror Force', '波纹防护罩－波动之力', '波紋のバリア －ウェーブ・フォース－', 'Trap Card', 'Normal', NULL, NULL, NULL, NULL, '①：对方怪兽的直接攻击宣言时才能发动。对方场上的攻击表示怪兽全部回到持有者卡组。'),
(97148796, 'Drytron Alpha Thuban', '辉龙机巧－右垣一阿尔法', '竜輝巧－バンα', 'Effect Monster', 'Machine', 'LIGHT', 1, 2000, NULL, '这张卡不能通常召唤，用「龙辉巧」卡的效果才能特殊召唤。这个卡名的效果1回合只能使用1次。 ①：把这张卡以外的自己的手卡·场上1只「龙辉巧」怪兽或仪式怪兽解放才能发动（这个效果发动的回合，自己若非不能通常召唤的怪兽则不能特殊召唤）。这张卡从手卡·墓地守备表示特殊召唤。那之后，可以从卡组把1只仪式怪兽加入手卡。'),
(57970721, 'Drytron Asterism', '星彩之辉龙机巧', '星彩の竜輝巧', 'Spell Card', 'Quick-Play', NULL, NULL, NULL, NULL, '这个卡名的卡在1回合只能发动1张。 ①：自己·对方的主要阶段，以自己场上1只「龙辉巧」怪兽或者仪式怪兽和对方场上1只表侧表示怪兽为对象才能发动。那只自己怪兽的攻击力直到对方回合结束时下降1000，那只对方怪兽破坏。'),
(33543890, 'Drytron Beta Rastaban', '辉龙机巧－天棓三贝塔', '竜輝巧－ラスβ', 'Effect Monster', 'Machine', 'LIGHT', 1, 2000, NULL, '这张卡不能通常召唤，用「龙辉巧」卡的效果才能特殊召唤。这个卡名的效果1回合只能使用1次。 ①：从自己的手卡·场上把1只这张卡以外的「龙辉巧」怪兽或者仪式怪兽解放才能发动。这张卡从手卡·墓地守备表示特殊召唤。那之后，可以选除外的1只自己的「龙辉巧」怪兽回到墓地。这个效果发动的回合，自己若非不能通常召唤的怪兽则不能特殊召唤。'),
(22420202, 'Drytron Delta Altais', '辉龙机巧－天厨一德尔塔', '竜輝巧－ルタδ', 'Effect Monster', 'Machine', 'LIGHT', 1, 2000, NULL, '这张卡不能通常召唤，用「龙辉巧」卡的效果才能特殊召唤。这个卡名的效果1回合只能使用1次。 ①：把这张卡以外的自己的手卡·场上1只「龙辉巧」怪兽或仪式怪兽解放才能发动（这个效果发动的回合，自己若非不能通常召唤的怪兽则不能特殊召唤）。这张卡从手卡·墓地守备表示特殊召唤。那之后，可以把手卡1只仪式怪兽或1张仪式魔法卡给对方观看让自己抽1张。'),
(21576077, 'Drytron Eclipse', '食光之辉龙机巧', '喰光の竜輝巧', 'Spell Card', 'Normal', NULL, NULL, NULL, NULL, '这个卡名的①②的效果1回合各能使用1次。 ①：以自己墓地1只「龙辉巧」怪兽为对象才能发动。那只怪兽加入手卡。 ②：把墓地的这张卡除外，以自己场上1只「龙辉巧」怪兽为对象才能发动。那只怪兽的攻击力直到对方回合结束时上升2000。这个效果在这张卡送去墓地的回合不能发动。'),
(58793369, 'Drytron Fafnir', '辉龙机巧－法夫纳', '竜輝巧－ファフニール', 'Spell Card', 'Field', NULL, NULL, NULL, NULL, '这个卡名的卡在1回合只能发动1张。 ①：作为这张卡的发动时的效果处理，可以从卡组把「龙辉巧-扶筐增二」以外的1张「龙辉巧」魔法·陷阱卡加入手卡。 ②：仪式魔法卡的效果的发动以及那些发动的效果不会被无效化。 ③：1回合1次，自己场上有「龙辉巧」怪兽存在的状态，怪兽表侧表示召唤·特殊召唤的场合才能发动。这个回合，那些表侧表示怪兽的等级下降那攻击力每1000为1星的数值（最少到1星）。'),
(60037599, 'Drytron Gamma Eltanin', '辉龙机巧－天棓四伽马', '竜輝巧－エルγ', 'Effect Monster', 'Machine', 'LIGHT', 1, 2000, NULL, '这张卡不能通常召唤，用「龙辉巧」卡的效果才能特殊召唤。这个卡名的效果1回合只能使用1次。 ①：把这张卡以外的自己的手卡·场上1只「龙辉巧」怪兽或仪式怪兽解放才能发动（这个效果发动的回合，自己若非不能通常召唤的怪兽则不能特殊召唤）。这张卡从手卡·墓地守备表示特殊召唤。那之后，可以从自己墓地把「龙辉巧-天棓四γ」以外的1只攻击力2000的「龙辉巧」怪兽特殊召唤。'),
(56863746, 'Drytron Meteonis DA Draconids', '仪龙机巧－降星：龙枢', '竜儀巧－メテオニス＝DAD', 'Ritual Effect Monster', 'Machine', 'LIGHT', 12, 5000, 5000, '「流星辉巧群」降临 ①：自己场上的其他的「龙辉巧」怪兽不会被对方的效果破坏。 ②：1回合最多2次，对方把怪兽的效果发动时，攻击力合计直到变成那只怪兽的原本攻击力以上为止从自己墓地把「龙辉巧」怪兽除外才能发动。那个发动无效并破坏。 ③：仪式召唤的这张卡被对方破坏的场合才能发动。从手卡·卡组把1只攻击力4000的仪式怪兽当作仪式召唤作特殊召唤。'),
(69815951, 'Drytron Meteonis Draconids', '仪龙机巧－降星：天龙', '竜儀巧－メテオニス＝DRA', 'Ritual Effect Monster', 'Machine', 'LIGHT', 12, 4000, 4000, '「流星辉巧群」降临 这个卡名的③的效果1回合只能使用1次。 ①：对方不能把场上的这张卡作为怪兽的效果的对象。 ②：这张卡的仪式召唤使用的怪兽的等级合计是2星以下的场合，这张卡可以向特殊召唤的对方怪兽全部各作1次攻击。 ③：对方回合，攻击力合计直到变成2000或4000为止从自己墓地把怪兽除外，以那个合计每2000为1张的对方场上的表侧表示卡为对象才能发动。那些卡送去墓地。'),
(95209656, 'Drytron Meteonis Quadrantids', '仪龙机巧－降星：象限仪', '竜儀巧－メテオニス＝QUA', 'Ritual Effect Monster', 'Machine', 'LIGHT', 12, 4000, 4000, '「流星辉巧群」降临。这个卡名的②③的效果1回合各能使用1次。 ①：场上的这张卡不会成为对方的魔法·陷阱卡的效果的对象。 ②：这张卡的仪式召唤使用的怪兽的等级合计是2星以下的场合才能发动。对方场上的魔法·陷阱卡全部破坏。 ③：仪式召唤的这张卡被破坏的场合才能发动。从自己墓地选攻击力合计直到变成4000为止的「龙仪巧-天龙流星QUA」以外的「龙辉巧」怪兽任意数量特殊召唤。'),
(84965420, 'Drytron Meteor Shower', '龙机巧流星群', 'ドライトロン流星群', 'Trap Card', 'Counter', NULL, NULL, NULL, NULL, '这个卡名的卡在1回合只能发动1张。 ①：自己场上有仪式怪兽存在，对方把怪兽召唤·特殊召唤之际才能发动。那个无效，那些怪兽回到持有者卡组。'),
(1174075, 'Drytron Mu Beta Fafnir', '辉龙机巧－法夫缪贝塔', '竜輝巧－ファフμβ’', 'XYZ Monster', 'Machine', 'LIGHT', 1, 2000, NULL, '1星怪兽×2只以上 这个卡名的①③的效果1回合各能使用1次。 ①：这张卡超量召唤的场合才能发动。从卡组把1张「龙辉巧」卡送去墓地。 ②：自己进行仪式召唤的场合，也能把那些解放的怪兽从这张卡的超量素材取除。 ③：自己场上有机械族仪式怪兽存在，对方把魔法·陷阱卡发动时，把这张卡1个超量素材取除才能发动。那个发动无效并破坏。'),
(94187078, 'Drytron Nova', '极超之辉龙机巧', '極超の竜輝巧', 'Spell Card', 'Normal', NULL, NULL, NULL, NULL, '这个卡名的卡在1回合只能发动1张，这张卡发动的回合，自己若非不能通常召唤的怪兽则不能特殊召唤。 ①：从卡组把1只「龙辉巧」怪兽特殊召唤。这个效果特殊召唤的怪兽在结束阶段破坏。'),
(22435424, 'Drytron Nu II', '辉龙机巧－天棓二纽兹', '竜輝巧－νⅡ', 'Effect Monster', 'Machine', 'LIGHT', 1, 2000, NULL, '这张卡不能通常召唤，用卡的效果才能特殊召唤。这个卡名的①②的效果1回合各能使用1次，这些效果发动的回合，自己不是机械族怪兽不能仪式召唤。 ①：场上有「龙辉巧」卡存在的场合才能发动。这张卡从手卡·墓地特殊召唤。这个效果特殊召唤的这张卡从场上离开的场合除外。 ②：这张卡特殊召唤的场合才能发动。从卡组把「龙辉巧-ν2」以外的1只「龙辉巧」怪兽加入手卡。'),
(96026108, 'Drytron Zeta Aldhibah', '辉龙机巧－左垣四截塔', '竜輝巧－アルζ', 'Effect Monster', 'Machine', 'LIGHT', 1, 2000, NULL, '这张卡不能通常召唤，用「龙辉巧」卡的效果才能特殊召唤。这个卡名的效果1回合只能使用1次。 ①：把这张卡以外的自己的手卡·场上1只「龙辉巧」怪兽或仪式怪兽解放才能发动（这个效果发动的回合，自己若非不能通常召唤的怪兽则不能特殊召唤）。这张卡从手卡·墓地守备表示特殊召唤。那之后，可以从卡组把1张仪式魔法卡加入手卡。'),
(7445307, 'Dual Assembwurm', '双汇编亚龙', 'デュアル・アセンブルム', 'Effect Monster', 'Cyberse', 'DARK', 8, 2800, 1000, '这个卡名的①的效果1回合只能使用1次。 ①：这张卡在手卡·墓地存在的场合，从手卡以及自己场上的表侧表示怪兽之中把2只电子界族怪兽除外才能发动。这张卡特殊召唤。这个效果特殊召唤的这张卡的攻击力变成一半。 ②：1回合1次，把1张手卡除外才能发动。选持有这张卡的攻击力以下的攻击力的场上1只怪兽除外。'),
(33026283, 'Dual Avatar - Empowered Kon-Gyo', '双天将 金刚', '双天将 金剛', 'Fusion Monster', 'Warrior', 'LIGHT', 8, 3000, 1700, '「双天拳之熊罴」＋「双天」怪兽×2 这个卡名的③的效果1回合只能使用1次。 ①：这张卡进行战斗的场合，对方直到伤害步骤结束时魔法·陷阱·怪兽的效果不能发动。 ②：这张卡攻击的伤害计算后才能发动。选对方场上1只怪兽回到持有者手卡。 ③：自己场上有融合怪兽2只以上存在，场上的这张卡为对象的对方的魔法·陷阱卡的效果发动时才能发动。那个发动无效。'),
(284224, 'Dual Avatar - Empowered Mitsu-Jaku', '双天将 密迹', '双天将 密迹', 'Fusion Monster', 'Warrior', 'LIGHT', 7, 2000, 3000, '「双天脚之鸿鹄」＋「双天」怪兽×2 这个卡名的③的效果1回合只能使用1次。 ①：只要这张卡在怪兽区域存在，自己的「双天」融合怪兽在1回合各有1次不会被战斗破坏。 ②：1回合1次，自己主要阶段才能发动。对方场上的魔法·陷阱卡全部回到持有者手卡。 ③：自己场上有融合怪兽2只以上存在，对方场上的怪兽的效果发动时才能发动。那只怪兽破坏。'),
(28798938, 'Dual Avatar - Manifested A-Un', '双天之狮使-阿吽', '双天の獅使－阿吽', 'Fusion Monster', 'Warrior', 'LIGHT', 4, NULL, NULL, '「双天」怪兽×2 ①：这张卡得到作为融合素材的怪兽的原本卡名的以下效果。 ●「双天将 金刚」：进行战斗的自己的「双天」怪兽的攻击力只在伤害计算时变成3000。 ●「双天将 密迹」：对方回合1次，以场上1张卡为对象才能发动。那张卡除外。 ②：融合召唤的这张卡被破坏的场合才能发动。从卡组把「双天拳之熊罴」「双天脚之鸿鹄」各1只特殊召唤。那些怪兽在这个回合不会被战斗·效果破坏。'),
(44644529, 'Dual Avatar Ascendance', '双天的转身', '双天の転身', 'Trap Card', 'Normal', NULL, NULL, NULL, NULL, '这个卡名的①②的效果1回合各能使用1次。 ①：以自己场上1只「双天」怪兽为对象才能发动。那只怪兽破坏，比那只怪兽原本等级高1星或者原本等级低1星的1只「双天」怪兽从卡组·额外卡组特殊召唤。 ②：自己主要阶段把墓地的这张卡除外，以自己墓地1只「双天」怪兽为对象才能发动。那只怪兽加入手卡。这个效果在这张卡送去墓地的回合不能发动。'),
(75157704, 'Dual Avatar Compact', '双天的使命', '双天の使命', 'Trap Card', 'Normal', NULL, NULL, NULL, NULL, '这个卡名的卡在1回合只能发动1张。 ①：自己·对方的主要阶段，把「双天的使命」以外的自己墓地1张「双天」魔法·陷阱卡除外才能发动。这张卡的效果变成和那张魔法·陷阱卡发动时的效果相同。'),
(49158617, 'Dual Avatar Defeating Evil', '双天的调伏', '双天の調伏', 'Spell Card', 'Quick-Play', NULL, NULL, NULL, NULL, '这个卡名的卡在1回合只能发动1张。 ①：以自己场上1只「双天」怪兽和对方场上1张卡为对象才能发动。那些卡破坏。这个效果把自己场上的「双天」融合怪兽破坏的场合，可以再从以下效果选1个适用。 ●自己从卡组抽1张。 ●从对方墓地选1张卡除外。'),
(7631534, 'Dual Avatar Feet - Armored Un-Gyo', '双天脚 铠吽', '双天脚 鎧吽', 'Fusion Monster', 'Warrior', 'LIGHT', 5, 1700, 2100, '「双天」怪兽×2 这个卡名的②的效果1回合只能使用1次。 ①：自己场上的「双天」融合怪兽被效果破坏的场合，可以作为代替把自己场上1只「双天」怪兽破坏。 ②：效果怪兽为素材作融合召唤的「双天」融合怪兽在自己场上存在的场合，自己·对方的主要阶段，以从额外卡组特殊召唤的1只表侧表示怪兽为对象才能发动。那只怪兽的效果直到回合结束时无效。'),
(11759079, 'Dual Avatar Feet - Kokoku', '双天脚之鸿鹄', '双天脚の鴻鵠', 'Effect Monster', 'Warrior', 'LIGHT', 3, 800, 2000, '这个卡名的①②的效果1回合各能使用1次。 ①：「双天脚之鸿鹄」以外的自己场上的表侧表示的「双天」怪兽在对方回合被战斗·效果破坏的场合才能发动。这张卡从手卡特殊召唤。那之后，以下效果可以适用。 ●选自己场上1只「双天」怪兽破坏，从额外卡组把1只「双天」融合怪兽特殊召唤。 ②：这张卡召唤·特殊召唤成功的场合才能发动。从卡组把1张「双天」陷阱卡加入手卡。'),
(60237530, 'Dual Avatar Fists - Armored Ah-Gyo', '双天拳 铠阿', '双天拳 鎧阿', 'Fusion Monster', 'Warrior', 'LIGHT', 6, 2100, 1500, '「双天」怪兽×2 这个卡名的①的效果1回合只能使用1次。 ①：这张卡特殊召唤成功的场合，以对方场上1只攻击表示怪兽为对象才能发动。那只怪兽破坏。这个效果的发动后，直到回合结束时这张卡不能直接攻击。 ②：只要效果怪兽为素材作融合召唤的「双天」融合怪兽在自己场上存在，自己场上的「双天」融合怪兽的攻击力·守备力上升300。'),
(85360035, 'Dual Avatar Fists - Yuhi', '双天拳之熊罴', '双天拳の熊羆', 'Effect Monster', 'Warrior', 'LIGHT', 4, 1800, 1000, '这个卡名的①②的效果1回合各能使用1次。 ①：以自己场上1只「双天」怪兽为对象才能发动。那只怪兽破坏，从卡组把1张「双天」魔法卡加入手卡。 ②：这张卡在墓地存在的状态，效果怪兽为素材作融合召唤的自己场上的表侧表示的「双天」融合怪兽被战斗或者对方的效果破坏的场合才能发动。这张卡加入手卡。'),
(87669904, 'Dual Avatar Invitation', '双天招来', '双天招来', 'Spell Card', 'Normal', NULL, NULL, NULL, NULL, '这个卡名的卡在1回合只能发动1张。 ①：丢弃1张手卡，在自己场上把「双天魂衍生物」（战士族·光·2星·攻/守0）尽可能特殊召唤。这个回合，自己不是融合怪兽不能从额外卡组特殊召唤，自己场上的衍生物不能解放并在结束阶段破坏。那之后，以下效果可以适用最多2次。 ●从自己的手卡·场上把「双天」融合怪兽卡决定的融合素材怪兽送去墓地，把那1只融合怪兽从额外卡组融合召唤。'),
(49752795, 'Dual Avatar Return', '双天的再来', '双天の再来', 'Trap Card', 'Normal', NULL, NULL, NULL, NULL, '这个卡名的卡在1回合只能发动1张。 ①：以自己墓地1只「双天」怪兽为对象才能发动。那只怪兽特殊召唤。这个效果把原本等级是4星以下的「双天」怪兽特殊召唤的场合，可以再在自己场上把1只「双天魂衍生物」（战士族·光·2星·攻/守0）特殊召唤。'),
(39973386, 'Duality', '表里一体', '表裏一体', 'Spell Card', 'Quick-Play', NULL, NULL, NULL, NULL, '这个卡名的①②的效果1回合各能使用1次。 ①：把自己场上1只光·暗属性怪兽解放才能发动。和那只怪兽是原本的种族·等级相同而原本属性不同的1只光·暗属性怪兽从手卡·额外卡组特殊召唤。 ②：自己主要阶段把墓地的这张卡除外，以自己墓地的光·暗属性怪兽各1只为对象才能发动。那2只怪兽回到卡组洗切。那之后，自己从卡组抽1张。'),
(11335209, 'Duamutef, Blessing of Horus', '荷鲁斯的祝福－杜阿木忒弗', 'ホルスの祝福－ドゥアムテフ', 'Effect Monster', 'Beast', 'WATER', 8, NULL, NULL, '这个卡名的①的方法的特殊召唤1回合只能有1次，③的效果1回合只能使用1次。 ①：自己场上有「王之棺」存在的场合，这张卡可以从墓地特殊召唤。 ②：这张卡的攻击力·守备力上升自己场上的「荷鲁斯」怪兽数量×1200。 ③：这张卡在怪兽区域存在的状态，自己场上的其他卡因对方的效果从场上离开的场合才能发动。自己抽出自己的主要怪兽区域的怪兽种类的数量。'),
(43803845, 'Duck Dummy', '假威鸭', 'ダックドロッパー', 'Gemini Monster', 'Winged Beast', 'WATER', 1, NULL, NULL, '①：这张卡只要在场上·墓地存在，当作通常怪兽使用。 ②：可以把场上的当作通常怪兽使用的这张卡作为通常召唤作再1次召唤。那个场合这张卡变成当作效果怪兽使用并得到以下效果。 ●这张卡不会成为效果的对象，不会被效果破坏。 ●只要这张卡在怪兽区域存在，对方怪兽的攻击全部变成直接攻击。'),
(54813225, 'Duck Fighter', '野鸭战斗机', 'ダックファイター', 'Effect Monster', 'Machine', 'WIND', 3, 1300, 1400, '把自己场上的衍生物那个等级合计直到3以上解放才能发动。这张卡从手卡或者墓地特殊召唤。「野鸭战斗机」的效果1回合只能使用1次。'),
(14506878, 'DUCKER Mobile Cannon', '二足炮台', 'ダッカー', 'Flip Effect Monster', 'Machine', 'LIGHT', 3, 500, 500, '①：这张卡反转的场合，以自己墓地1只4星怪兽为对象发动。那只怪兽加入手卡。'),
(5833312, 'Duel Academy', '决斗学园', 'デュエル・アカデミア', 'Spell Card', 'Field', NULL, NULL, NULL, NULL, '①：得到场上的怪兽种族的以下效果。 ●战士族·兽族·炎族：1回合1次，自己把陷阱卡发动的场合，以对方场上1张卡为对象才能发动。那张卡破坏。 ●恐龙族·海龙族·雷族：1回合1次，自己把魔法卡发动的场合才能发动。给与对方1000伤害。 ●机械族·天使族·恶魔族：1回合1次，自己把怪兽的效果发动的场合，以自己场上1只表侧表示怪兽为对象才能发动。那只怪兽的攻击力上升1000。'),
(91002901, 'Duel Evolution - Assault Zone', '决斗进化－爆裂领域', '決闘進化－バスター・ゾーン', 'Spell Card', 'Field', NULL, NULL, NULL, NULL, '这个卡名的卡在1回合只能发动1张，这个卡名的③的效果1回合只能使用1次。 ①：作为这张卡的发动时的效果处理，可以从自己的卡组·墓地把有「爆裂模式」的卡名记述的1只怪兽加入手卡。 ②：「/爆裂体」怪兽在特殊召唤的回合不会被战斗以及对方的效果破坏。 ③：支付2000基本分才能发动。这个回合只有1次，可以从额外卡组选自己要为「爆裂模式」发动而解放的同调怪兽。'),
(60025883, 'Duel Link Dragon, the Duel Dragon', '决斗龙 决斗连接龙', '決闘竜 デュエル・リンク・ドラゴン', 'Link Monster', 'Dragon', 'DARK', NULL, NULL, NULL, '包含同调怪兽的怪兽2只以上 这个卡名的①的效果1回合只能使用1次。 ①：自己·对方的主要阶段，从额外卡组把1只「动力工具」同调怪兽或者7·8星的龙族同调怪兽除外才能发动。把持有和那只怪兽相同种族·属性·等级·攻击力·守备力的1只「决斗龙衍生物」在作为这张卡所连接区的自己场上特殊召唤。 ②：自己场上有「决斗龙衍生物」存在的场合，对方不能选择这张卡作为攻击对象，也不能作为效果的对象。'),
(43940008, 'Duel Tower', '决斗塔 阿尔卡特拉斯', '決闘塔アルカトラズ', 'Spell Card', 'Field', NULL, NULL, NULL, NULL, '①：自己·对方的战斗阶段开始时发动。双方各自可以从自身卡组选1只攻击力?以外的怪兽。选的怪兽给双方确认，里侧表示除外。选攻击力最高的怪兽的玩家可以从手卡把1只怪兽特殊召唤。这个效果特殊召唤的怪兽可以直接攻击。 ②：自己·对方的结束阶段才能发动。下次的自己回合的结束阶段有这张卡在场上存在的场合，场上的卡全部破坏。'),
(37469904, 'Duelist Alliance', '决斗者降临', 'デュエリスト・アドベント', 'Spell Card', 'Normal', NULL, NULL, NULL, NULL, '这个卡名的卡在1回合只能发动1张。 ①：自己或对方的灵摆区域有卡存在的场合才能发动。从卡组把1只「灵摆」灵摆怪兽或1张「灵摆」魔法·陷阱卡加入手卡。'),
(97474300, 'Duelist Genesis', '决斗者创世', 'デュエリスト・ジェネシス', 'Spell Card', 'Normal', NULL, NULL, NULL, NULL, '这个卡名的卡在1回合只能发动1张。 ①：自己的场上或墓地有调整存在的场合才能发动。从卡组把1张「同调」魔法·陷阱卡加入手卡。'),
(37880706, 'Duelittle Chimera', '怠惰小奇美拉', 'ドリトル・キメラ', 'Link Monster', 'Beast', 'FIRE', NULL, 1400, NULL, '炎属性怪兽2只 这个卡名的②的效果1回合只能使用1次。 ①：场上的炎属性怪兽的攻击力·守备力上升500，水属性怪兽的攻击力·守备力下降400。 ②：这张卡被战斗·效果破坏的场合，以自己墓地1只炎属性怪兽为对象才能发动。那只怪兽加入手卡。'),
(19162134, 'Dueltaining', '娱乐决斗', 'エンタメデュエル', 'Spell Card', 'Field', NULL, NULL, NULL, NULL, '①：只要这张卡在场地区域存在，双方玩家每次在1回合中各把以下条件满足，每1个条件在1回合各有1次从卡组抽2张。 ●把等级不同的怪兽5只同时特殊召唤。 ●自身1只怪兽进行5次战斗。 ●连锁5以上把卡的效果发动。 ●掷骰子的次数以及投掷硬币的次数变成合计5次。 ●受到让自身基本分变成500以下的伤害。'),
(85154941, 'Duke Archfiend', '公爵恶魔', 'デューク・デーモン', 'Effect Monster', 'Fiend', 'WATER', 4, NULL, 2000, '这个卡名的②③的效果1回合各能使用1次。 ①：这张卡的攻击力上升这张卡的等级×200。 ②：以自己场上1只表侧表示怪兽为对象才能发动。从卡组把「公爵恶魔」以外的1只「恶魔」怪兽送去墓地。作为对象的怪兽的等级上升送去墓地的怪兽的等级数值。 ③：这张卡在墓地存在的状态，自己的仪式怪兽被战斗破坏时才能发动。这张卡特殊召唤。'),
(12766474, 'Duke Shade, the Sinister Shadow Lord', '影王 阴暗公爵', '影王デュークシェード', 'Effect Monster', 'Fiend', 'DARK', 4, 500, 2000, '这个卡名的①②的效果1回合各能使用1次，这张卡的效果发动的回合，自己不是暗属性怪兽不能特殊召唤。 ①：把自己场上的暗属性怪兽任意数量解放才能发动。这张卡从手卡特殊召唤。这个效果特殊召唤的这张卡的攻击力上升解放的怪兽数量×500。 ②：这张卡召唤·特殊召唤成功的场合，以自己墓地1只5星以上的暗属性怪兽为对象才能发动。那只怪兽加入手卡。'),
(13532663, 'Dummy Golem', '替身石人', 'ダミー・ゴーレム', 'Flip Effect Monster', 'Rock', 'EARTH', 2, 800, 800, '反转：对方选择所控制的1只怪兽。选择怪兽和这张卡的控制权交换。'),
(12493482, 'Dunames Dark Witch', '美德女武神', 'デュナミス・ヴァルキリア', 'Normal Monster', 'Fairy', 'LIGHT', 4, 1800, 1050, '勇敢的光之天使。出于那强烈的正义感，明知必败也决不逃避与邪恶的战斗。'),
(51228280, 'Dungeon Worm', '迷宫的蠕虫', 'ダンジョン・ワーム', 'Normal Monster', 'Insect', 'EARTH', 5, 1800, 1500, '潜在迷路者的地下，捕食经过此处迷路的生物。'),
(65952776, 'Dunnell, the Noble Arms of Light', '光之圣剑 宕奈尔', '光の聖剣ダンネル', 'Spell Card', 'Equip', NULL, NULL, NULL, NULL, '自己场上的怪兽才能装备。这个卡名的③的效果1回合只能使用1次。 ①：「光之圣剑 丹内尔」在自己场上只能有1张表侧表示存在。 ②：装备怪兽的攻击力上升自己场上的有「勇者衍生物」的衍生物名记述的怪兽种类×500。 ③：这张卡被送去墓地的场合，以自己场上1只「勇者衍生物」为对象才能发动。那只自己怪兽把这张卡装备。'),
(43017476, 'Duoterion', '氘素龙', 'デューテリオン', 'Effect Monster', 'Dinosaur', 'WATER', 5, 2000, 1400, '这个卡名的①②的效果1回合各能使用1次。 ①：自己主要阶段把这张卡从手卡丢弃才能发动。从卡组把1张「结合术」魔法·陷阱卡加入手卡。 ②：这张卡召唤·特殊召唤成功的场合，以自己墓地的「氢素龙」「氧素龙」「氘素龙」的其中1只为对象才能发动。那只怪兽特殊召唤。'),
(46239604, 'Dupe Frog', '魔知青蛙', '魔知ガエル', 'Effect Monster', 'Aqua', 'WATER', 2, 100, 2000, '①：这张卡只要在怪兽区域存在，卡名当作「死亡青蛙」使用。 ②：只要这张卡在怪兽区域存在，对方不能选择其他怪兽作为攻击对象。 ③：这张卡从场上送去墓地时才能发动。从自己的卡组·墓地选「魔知青蛙」以外的1只「青蛙」怪兽加入手卡。'),
(76821171, 'Duralume, Vaalmonican Heathen Hallow', '华耳琴璃之异神－誓拉尔梅', 'ヴァルモニカの異神－ジュラルメ', 'Link Monster', 'Fairy', 'DARK', NULL, 2500, NULL, '效果怪兽1只 这张卡的连接召唤若非自己的灵摆区域的天使族怪兽卡的响鸣指示物是3个以上的场合则不能进行，自己对「异响鸣之异神-光耀天使」1回合只能有1次特殊召唤。 ①：这张卡连接召唤的场合，以最多有自己的灵摆区域的响鸣指示物数量的对方场上的怪兽为对象才能发动。那些怪兽破坏。 ②：把自己的灵摆区域3个响鸣指示物取除才能发动。这个回合，这张卡在同1次的战斗阶段中可以作3次攻击。'),
(31476755, 'Dust Barrier', '沙尘之结界', '砂塵の結界', 'Spell Card', 'Continuous', NULL, NULL, NULL, NULL, '场上所有以表侧表示存在的通常怪兽不受对方魔法卡效果的影响。在这张卡发动后的第2个自己的准备阶段时，这张卡被破坏。'),
(35195612, 'Dust Knight', '沙尘之骑士', '砂塵の騎士', 'Flip Effect Monster', 'Warrior', 'EARTH', 4, 1400, 1200, '反转：从卡组把1只地属性怪兽送去墓地。'),
(8414337, 'Dust Storm of Gusto', '薰风的风尘', 'ガスタの風塵', 'Trap Card', 'Normal', NULL, NULL, NULL, NULL, '这张卡发动的回合，自己场上存在的名字带有「薰风」的怪兽的攻击宣言时，对方不能把魔法·陷阱·效果怪兽的效果发动。'),
(60082869, 'Dust Tornado', '沙尘大龙卷', '砂塵の大竜巻', 'Trap Card', 'Normal', NULL, NULL, NULL, NULL, '①：以对方场上1张魔法·陷阱卡为对象才能发动。那张对方的卡破坏。那之后，可以从手卡把1张魔法·陷阱卡盖放。'),
(38049934, 'Dustflame Blast', '炎尘爆发', '炎塵爆発', 'Trap Card', 'Normal', NULL, NULL, NULL, NULL, '把自己墓地存在的名字带有「熔岩」的怪兽全部从游戏中除外发动。把最多有除外的怪兽数量的场上存在的卡破坏。'),
(25700114, 'Duston Roller', '尘妖滚筒', 'ダストンローラー', 'Trap Card', 'Normal', NULL, NULL, NULL, NULL, '选择场上1只怪兽才能发动。这个回合，选择的怪兽不能解放，也不能作为融合·同调·超量召唤的素材。此外，盖放的这张卡被对方的卡的效果破坏送去墓地的场合，可以从卡组把1只名字带有「尘妖」的怪兽加入手卡。'),
(20137754, 'Duza the Meteor Cubic Vessel', '流星方界器 天尘', '流星方界器デューザ', 'Effect Monster', 'Machine', 'LIGHT', 4, 1600, 1600, '①：这张卡召唤·特殊召唤成功的场合才能发动。从卡组把1张「方界」卡送去墓地。 ②：1回合1次，这张卡表侧表示存在的状态，怪兽被送去自己墓地的回合才能发动。这张卡的攻击力直到回合结束时上升自己墓地的怪兽种类×200。这个效果在对方回合也能发动。'),
(13455953, 'Dverg of the Nordic Alfar', '极星灵 矮人', '極星霊ドヴェルグ', 'Effect Monster', 'Warrior', 'EARTH', 1, 100, 1000, '这张卡召唤成功的回合，自己在通常召唤外加上只有1次可以把1只名字带有「极星」的怪兽召唤。场上表侧表示存在的这张卡被送去墓地时，从自己墓地选择1张名字带有「极星宝」的卡加入手卡。'),
(67310848, 'Dwarf Star Dragon Planeter', '矮星龙 普朗涅特', '矮星竜 プラネター', 'Effect Monster', 'Dragon', 'LIGHT', 4, 1700, 1200, '①：这张卡召唤的回合的结束阶段才能发动。从卡组把1只光属性或者暗属性的7星怪兽加入手卡。'),
(46508640, 'Dweller in the Depths', '龙脉栖息者', '龍脈に棲む者', 'Effect Monster', 'Dragon', 'EARTH', 3, 1500, 700, '①：这张卡的攻击力上升自己的魔法与陷阱区域的永续魔法卡数量×300。'),
(46984349, 'Dwimmered Glimmer', '救魔之奇石', '救魔の奇石', 'Trap Card', 'Continuous', NULL, NULL, NULL, NULL, '这个卡名的卡在1回合只能发动1张。 ①：把自己场上1只表侧表示怪兽或者自己墓地1只怪兽除外才能把这张卡发动。这张卡发动后变成持有和除外的怪兽的原本等级相同等级的通常怪兽（魔法师族·光·攻/守0）在怪兽区域特殊召唤。这张卡也当作陷阱卡使用。'),
(24721709, 'Dwimmered Path', '救魔之标', '救魔の標', 'Spell Card', 'Normal', NULL, NULL, NULL, NULL, '这个卡名的卡在1回合只能发动1张。 ①：以自己墓地1只魔法师族效果怪兽为对象才能发动。那只怪兽加入手卡。'),
(39396763, 'Dyna Base', '恐龙底座', 'ダイナ・ベース', 'Effect Monster', 'Machine', 'EARTH', 4, NULL, 2100, '这个卡名的①②的效果1回合各能使用1次。 ①：自己基本分比对方少的场合才能发动。这张卡从手卡特殊召唤。 ②：自己主要阶段才能发动。融合怪兽卡决定的包含场上的这张卡的融合素材怪兽从自己的手卡·场上送去墓地，把那1只融合怪兽从额外卡组融合召唤。'),
(73898890, 'Dyna Mondo', '大傩主水', '大儺主水', 'Link Monster', 'Cyberse', 'EARTH', NULL, 2200, NULL, '包含仪式怪兽的怪兽2只 这个卡名的①②的效果1回合各能使用1次。 ①：这张卡特殊召唤的场合，以场上1张卡和自己墓地1只仪式怪兽为对象才能发动。那2张回到卡组。 ②：对方回合，把这张卡解放，以自己墓地1只仪式怪兽为对象才能发动。那只怪兽加入手卡或特殊召唤。'),
(75780818, 'Dyna Tank', '恐龙战车', 'ダイナ・タンク', 'Fusion Monster', 'Machine', 'EARTH', 7, -1, 2100, '机械族怪兽＋恐龙族怪兽 这个卡名的②③的效果1回合各能使用1次。 ①：这张卡的攻击力上升作为这张卡的融合素材的恐龙族怪兽的原本攻击力数值。 ②：只以场上的这1张卡为对象的效果发动时，以这张卡以外的场上1张卡为对象才能发动。那个对象转移为作为正确对象的那张卡。 ③：这张卡被对方破坏的场合才能发动。从自己墓地选1只恐龙族怪兽特殊召唤。'),
(25123713, 'Dyna, Hero Fur Hire', '空牙团的豪杰 戴拿', '空牙団の豪傑 ダイナ', 'Effect Monster', 'Beast-Warrior', 'EARTH', 6, 2500, 1400, '这个卡名的①的效果1回合只能使用1次。 ①：这张卡特殊召唤成功的场合才能发动。选最多有自己场上的「空牙团」怪兽种类数量的对方墓地的卡除外。 ②：只要这张卡在怪兽区域存在，对方不能选择其他的「空牙团」怪兽作为攻击对象。'),
(7409792, 'Dynatherium', '俊足犀牛 马力巨犀', '俊足なカバ バリキテリウム', 'Effect Monster', 'Beast', 'WIND', 4, 1600, 600, '这个卡名的①的方法的特殊召唤1回合只能有1次。 ①：这张卡可以从手卡特殊召唤。 ②：这张卡的①的方法特殊召唤成功的场合发动。对方可以从自己或者对方的墓地选1只4星怪兽在自身场上特殊召唤。'),
(52085072, 'Dystopia the Despondent', '绝望神 安提霍普', '絶望神アンチホープ', 'Effect Monster', 'Fiend', 'DARK', 12, 5000, 5000, '这张卡不能通常召唤。把自己场上4只表侧表示的1星怪兽送去墓地的场合才能从手卡·墓地特殊召唤。 ①：只要这张卡在怪兽区域存在，其他的自己怪兽不能攻击。 ②：这张卡进行战斗的战斗步骤中1次，把自己墓地1只1星怪兽除外才能发动。这张卡直到那次伤害步骤结束时不受其他卡的效果影响，不会被战斗破坏。'),
(6330307, 'DZW - Chimera Clad', '暗黑异热同心武器-魔装鵺妖衣', 'DZW－魔装鵺妖衣', 'Effect Monster', 'Fiend', 'DARK', 1, NULL, NULL, '自己的主要阶段时，手卡或者自己场上的这只怪兽可以当作装备卡使用给自己场上的名字带有「混沌No.39」的怪兽装备。此外，这张卡当作装备卡使用而装备中的场合，装备怪兽不会被战斗破坏。装备怪兽的攻击没让对方怪兽被破坏的伤害步骤结束时，可以把那只对方怪兽的攻击力变成0并只再1次可以向同只怪兽继续攻击。'),
(213326, 'E - Emergency Call', 'E－紧急呼救', 'E－エマージェンシーコール', 'Spell Card', 'Normal', NULL, NULL, NULL, NULL, '①：从卡组把1只「元素英雄」怪兽加入手卡。'),
(49139666, 'E Stranger Big Bang', '异星战队 大爆炸连者', '異星戦隊 ビッグ・バン', 'Effect Monster', 'Warrior', 'LIGHT', 5, 2100, 500, '这个卡名的①②③的效果1回合各能使用1次。 ①：从额外卡组特殊召唤的怪兽在场上存在的场合才能发动。这张卡从手卡特殊召唤。 ②：自己主要阶段才能发动。这张卡以外的场上的全部怪兽的等级下降1星。这张卡的等级上升所降的怪兽数量的数值。 ③：自己战斗阶段以及对方主要阶段，这张卡的等级是8星以上的场合才能发动。场上1张其他卡破坏，这张卡的等级变成5星。'),
(17427333, 'E.M.R.', '电磁轨道炮', 'E.M.R.', 'Trap Card', 'Normal', NULL, NULL, NULL, NULL, '①：把自己场上1只机械族怪兽解放，以解放的怪兽的原本攻击力每1000最多1张的场上的卡为对象才能发动。那些卡破坏。'),
(53693416, 'Eagle Eye', '鹰眼', 'イーグル・アイ', 'Effect Monster', 'Winged Beast', 'WIND', 3, 1300, 1200, '这张卡召唤成功时，陷阱卡不能发动。'),
(7500772, 'Eagle Shark', '鹰鲨', 'イーグル・シャーク', 'Effect Monster', 'Fish', 'WATER', 5, 1000, 1800, '对方场上的怪兽是2只以上的场合，这张卡可以不用解放作召唤。此外，自己场上有「豹鲨」存在的场合，这张卡可以从手卡特殊召唤。「鹰鲨」在自己场上只能有1只表侧表示存在。'),
(9416697, 'Eanoc, Sentry of the Ghoti', '游魊之看守 伊诺可', 'ゴーティスの守人イーノック', 'Effect Monster', 'Fish', 'WATER', 6, 2100, NULL, '这个卡名的①②的效果1回合各能使用1次。 ①：这张卡召唤·特殊召唤的场合，以自己的除外状态的1只4星以下的鱼族怪兽为对象才能发动。那只怪兽守备表示特殊召唤。这个效果特殊召唤的怪兽的效果无效化。 ②：从自己的手卡·场上（表侧表示）把1只鱼族怪兽除外才能发动。从卡组把1张「魊影」陷阱卡加入手卡。'),
(58995660, 'Early Palm Gets the Win', '先手必掌', '先手必掌', 'Spell Card', 'Continuous', NULL, NULL, NULL, NULL, '①：1回合1次，自己怪兽进行战斗的攻击宣言时才能发动。掷1次骰子，出现的数目的以下效果对那只自己怪兽直到回合结束时适用。相同纵列的怪兽之间进行战斗的攻击宣言时发动的场合，不掷骰子从以下效果选1个。 ●1·4：只有1次不会被战斗·效果破坏。 ●2·5：攻击力下降500，不受「先手必掌」以外的魔法·陷阱卡发动的效果影响。 ●3·6：攻击力上升1000，同1次的战斗阶段中最多2次可以向怪兽攻击。'),
(22812068, 'Earth Armor Ninja', '机甲忍者 地', '機甲忍者アース', 'Effect Monster', 'Warrior', 'EARTH', 5, 1600, 1200, '对方场上有怪兽存在，自己场上没有怪兽存在的场合，这张卡可以从手卡特殊召唤。'),
(59820352, 'Earth Chant', '大地赞颂', '大地讃頌', 'Spell Card', 'Ritual', NULL, NULL, NULL, NULL, '可以使地属性的仪式怪兽降临。特殊召唤时，必须以场上和/或手卡中合计等级与此地属性仪式怪兽等级相同的怪兽作为祭品。'),
(53461122, 'Earth Effigy', '地构体', 'ガイアフレーム', 'Effect Monster', 'Rock', 'EARTH', 4, 100, 2000, '地属性的通常怪兽祭品召唤的场合，这1只怪兽可以作为2只的数量的祭品。'),
(62111090, 'Earth Golem @Ignister', '地魔像＠伊格尼斯者', 'アースゴーレム＠イグニスター', 'Fusion Monster', 'Cyberse', 'EARTH', 7, 2300, 2000, '电子界族怪兽＋连接怪兽 这个卡名的③的效果1回合只能使用1次。 ①：这张卡融合召唤成功的回合，自己受到的全部伤害变成0。 ②：向从额外卡组特殊召唤的怪兽用这张卡攻击的伤害步骤内，这张卡的攻击力上升原本攻击力数值。 ③：这张卡被战斗破坏时，以「地石人@火灵天星」以外的自己墓地1只电子界族怪兽为对象才能发动。那只怪兽特殊召唤。'),
(99599062, 'Earthbound Fusion', '地缚融合', '地縛融合', 'Spell Card', 'Quick-Play', NULL, NULL, NULL, NULL, '这个卡名的②的效果1回合只能使用1次。这张卡在场地区域没有卡存在的场合，不在自己·对方的主要阶段不能发动。 ①：自己的手卡·场上的怪兽作为融合素材，把1只暗属性融合怪兽融合召唤。 ②：场地区域有卡存在的场合，自己主要阶段把墓地的这张卡除外才能发动。从自己的手卡·墓地把1只「地缚」怪兽特殊召唤。这个回合，自己不是融合·同调怪兽不能从额外卡组特殊召唤。'),
(44710391, 'Earthbound Geoglyph', '地缚地画', '地縛地上絵', 'Spell Card', 'Field', NULL, NULL, NULL, NULL, '这个卡名的③的效果1回合只能使用1次。 ①：只要场上有10星怪兽存在，这张卡不会被效果破坏，双方不能把这张卡作为效果的对象。 ②：只要这张卡在场地区域存在，自己把「地缚神」怪兽上级召唤的场合，同调怪兽可以作为2只的数量解放。 ③：同调怪兽特殊召唤的场合才能发动。从卡组把1张「地缚神」魔法·陷阱卡加入手卡。'),
(45836982, 'Earthbound Greater Linewalker', '地缚超神官', '地縛超神官', 'Effect Monster', 'Fiend', 'DARK', 8, 2900, 2900, '这个卡名的①②③的效果1回合各能使用1次。 ①：同调怪兽在自己的场上·墓地的两方存在的场合才能发动。这张卡从手卡特殊召唤。 ②：自己主要阶段才能发动。从自己的卡组·墓地把1只「地缚神」怪兽加入手卡。 ③：这张卡已在怪兽区域存在的状态，「地缚神」怪兽召唤的场合才能发动。对方基本分变成3000。'),
(10875327, 'Earthbound Immortal Aslla piscu', '地缚神 Aslla piscu', '地縛神 Aslla piscu', 'Effect Monster', 'Winged Beast', 'DARK', 10, 2500, 2500, '①：「地缚神」怪兽在场上只能有1只表侧表示存在。 ②：这张卡可以直接攻击。 ③：对方怪兽不能选择这张卡作为攻击对象。 ④：没有场地魔法卡表侧表示存在的场合这张卡破坏。 ⑤：表侧表示的这张卡因这张卡的效果以外的方法从场上离开的场合发动。对方场上的表侧表示怪兽全部破坏，给与对方破坏数量×800伤害。'),
(46263076, 'Earthbound Immortal Ccapac Apu', '地缚神 Ccapac Apu', '地縛神 Ccapac Apu', 'Effect Monster', 'Fiend', 'DARK', 10, 3000, 2500, '名字带有「地缚神」的怪兽在场上只能有1只表侧表示存在。场上没有表侧表示场地魔法卡存在的场合这张卡破坏。对方不能选择这张卡作为攻击对象。这张卡可以直接攻击对方玩家。这张卡战斗破坏对方怪兽的场合，给与对方基本分破坏怪兽的攻击力数值的伤害。'),
(79798060, 'Earthbound Immortal Ccarayhua', '地缚神 Ccarayhua', '地縛神 Ccarayhua', 'Effect Monster', 'Reptile', 'DARK', 10, 2800, 1800, '名字带有「地缚神」的怪兽在场上只能有1只表侧表示存在。场上没有表侧表示场地魔法卡存在的场合这张卡破坏。对方不能选择这张卡作为攻击对象。这张卡可以直接攻击对方玩家。这张卡的效果以外的效果让这张卡破坏时，场上存在的卡全部破坏。'),
(69931927, 'Earthbound Immortal Chacu Challhua', '地缚神 Chacu Challhua', '地縛神 Chacu Challhua', 'Effect Monster', 'Fish', 'DARK', 10, 2900, 2400, '名字带有「地缚神」的怪兽在场上只能有1只表侧表示存在。场上没有表侧表示场地魔法卡存在的场合这张卡破坏。对方不能选择这张卡作为攻击对象。这张卡可以直接攻击对方玩家。1回合1次，可以给与对方基本分这张卡的守备力一半数值的伤害。这个效果发动的回合，这张卡不能攻击。此外，这张卡在场上表侧守备表示存在的场合，对方不能进行战斗阶段。'),
(33537328, 'Earthbound Immortal Cusillu', '地缚神 Cusillu', '地縛神 Cusillu', 'Effect Monster', 'Beast', 'DARK', 10, 2800, 2400, '名字带有「地缚神」的怪兽在场上只能有1只表侧表示存在。场上没有表侧表示场地魔法卡存在的场合这张卡破坏。对方不能选择这张卡作为攻击对象。这张卡可以直接攻击对方玩家。自己场上表侧表示存在的这张卡被战斗破坏的场合，可以作为代替把自己场上存在的1只怪兽解放，对方基本分变成一半数值。'),
(5267507, 'Earthbound Immortal Red Nova', '地缚神 绯暗红新星', '地縛神 スカーレッド・ノヴァ', 'Effect Monster', 'Fiend', 'DARK', 12, 3500, 3000, '这个卡名的②的效果1回合只能使用1次。 ①：「地缚神」怪兽在场上只能有1只表侧表示存在。 ②：自己·对方的主要阶段，把手卡·墓地的这张卡除外才能发动。从自己的手卡·场上（表侧表示）把1只「地缚神」怪兽或「红莲魔龙」送去墓地。那之后，可以从以下效果让1个适用。 ●从卡组·额外卡组把1只「地缚」怪兽特殊召唤。 ●从额外卡组把1只「真红莲新星龙」当作同调召唤作特殊召唤。'),
(64187086, 'Earthbound Immortal Revival', '地缚神的复活', '地縛神の復活', 'Spell Card', 'Normal', NULL, NULL, NULL, NULL, '丢弃1张手卡发动。选择自己墓地存在的1只名字带有「地缚神」的怪兽和1张场地魔法卡加入手卡。'),
(15187079, 'Earthbound Immortal Uru', '地缚神 Uru', '地縛神 Uru', 'Effect Monster', 'Insect', 'DARK', 10, 3000, 3000, '名字带有「地缚神」的怪兽在场上只能有1只表侧表示存在。场上没有表侧表示场地魔法卡存在的场合这张卡破坏。对方不能选择这张卡作为攻击对象。这张卡可以直接攻击对方玩家。1回合1次，可以把这张卡以外的自己场上存在的1只怪兽解放，选择对方场上表侧表示存在的1只怪兽，直到这个回合的结束阶段时得到控制权。'),
(41181774, 'Earthbound Immortal Wiraqocha Rasca', '地缚神 Wiraqocha Rasca', '地縛神 Wiraqocha Rasca', 'Effect Monster', 'Winged Beast', 'DARK', 10, 100, 100, '①：「地缚神」怪兽在场上只能有1只表侧表示存在。 ②：这张卡召唤成功的场合，以最多有对方手卡数量的这张卡以外的自己场上的卡为对象发动（最多3张）。那些卡回到持有者卡组。那之后，对方手卡随机选回去的数量丢弃，这张卡的攻击力上升丢弃数量×1000。 ③：这张卡可以直接攻击。 ④：对方不能选择这张卡作为攻击对象。 ⑤：没有场地魔法卡表侧表示存在的场合这张卡破坏。'),
(67987302, 'Earthbound Linewalker', '地缚大神官', '地縛大神官', 'Effect Monster', 'Fiend', 'DARK', 4, 1200, 1900, '①：只要这张卡在怪兽区域存在，「地缚神」怪兽不会被自身的效果破坏。'),
(71089030, 'Earthbound Prison', '地缚牢', '地縛牢', 'Spell Card', 'Field', NULL, NULL, NULL, NULL, '①：这张卡的发动时，可以以对方场上1只效果怪兽为对象。那个场合，这张卡得到以下效果。 ●只要这张卡在场地区域存在，作为对象的效果怪兽的效果无效化。 ②：自己在通常召唤外加上只有1次，自己主要阶段可以把1只「地缚」怪兽召唤。 ③：这张卡被对方的效果破坏的场合，若自己的场上或墓地有「地缚」怪兽存在则发动。对方基本分变成一半，对方场上的全部表侧表示卡的效果直到回合结束时无效。'),
(46939151, 'Earthbound Prisoner Ground Keeper', '地缚囚人 大地看守者', '地縛囚人 グランド・キーパー', 'Tuner Monster', 'Fiend', 'DARK', 1, 300, 300, '这个卡名的①的效果1回合只能使用1次。 ①：这张卡召唤·特殊召唤的场合才能发动。除「地缚囚人 土地看守者」外的1只5星以下的「地缚」怪兽从自己的卡组·墓地特殊召唤。这个效果的发动后，直到回合结束时自己不是融合·同调怪兽不能从额外卡组特殊召唤。 ②：只要场地区域有卡存在，自己场上的「地缚」怪兽不会被战斗·效果破坏。'),
(19322865, 'Earthbound Prisoner Line Walker', '地缚囚人 地线巡视者', '地縛囚人 ライン・ウォーカー', 'Tuner Monster', 'Fiend', 'DARK', 3, 800, 1100, '这个卡名的①②的效果1回合各能使用1次。 ①：这张卡召唤·特殊召唤的场合才能发动。从自己的卡组·墓地把1张「地缚牢」或「异界共鸣-同调融合」加入手卡。 ②：自己场上有6星以上的「地缚」怪兽存在的场合，把墓地的这张卡除外，以从额外卡组特殊召唤的对方场上1只效果怪兽为对象才能发动。那只效果怪兽回到卡组。那之后，对方可以把那1只同名怪兽从自身的额外卡组特殊召唤。'),
(72323266, 'Earthbound Prisoner Stone Sweeper', '地缚囚人 岩石清扫者', '地縛囚人 ストーン・スィーパー', 'Effect Monster', 'Fiend', 'DARK', 5, 1600, 1600, '这个卡名的①的方法的特殊召唤1回合只能有1次，②的效果1回合只能使用1次。 ①：场地区域有卡存在的场合，这张卡可以从手卡特殊召唤。 ②：把这张卡从手卡丢弃才能发动。从卡组把1只3星以下的恶魔族调整加入手卡。这个效果的发动后，直到回合结束时自己不是融合·同调怪兽不能从额外卡组特殊召唤。'),
(84262395, 'Earthbound Release', '地缚解放', '地縛解放', 'Trap Card', 'Normal', NULL, NULL, NULL, NULL, '①：场上有6星以上的怪兽召唤·特殊召唤时，把自己场上1只10星「地缚」怪兽解放才能发动。对方场上的怪兽全部破坏，给与对方破坏的怪兽的原本攻击力合计数值的伤害。'),
(95207988, 'Earthbound Resonance', '地缚共振', '地縛共振', 'Trap Card', 'Continuous', NULL, NULL, NULL, NULL, '这个卡名的①②的效果1回合各能使用1次。 ①：从额外卡组特殊召唤的场上的怪兽被效果破坏的场合，以那之内的1只为对象才能发动。双方受到那只怪兽的攻击力一半数值的伤害。 ②：从额外卡组特殊召唤的自己的暗属性同调怪兽被选择作为攻击对象时，以场上1张卡为对象才能发动。那张卡破坏。'),
(71101678, 'Earthbound Servant Geo Grasha', '地缚戒隶 地画格剌希亚拉波斯', '地縛戒隷 ジオグラシャ＝ラボラス', 'Fusion Monster', 'Fiend', 'DARK', 10, 3000, 1800, '「地缚」融合怪兽＋「地缚」同调怪兽 这张卡不用融合召唤不能特殊召唤。这个卡名的②的效果1回合只能使用1次。 ①：这张卡和怪兽进行战斗的伤害步骤开始时发动。那只怪兽的攻击力·守备力变成0。 ②：对方怪兽被战斗·效果破坏的场合才能发动。对方场上的卡全部破坏。 ③：表侧表示的这张卡因对方从场上离开的场合才能发动。从卡组·额外卡组把1只「地缚」怪兽特殊召唤。'),
(8690387, 'Earthbound Servant Geo Gremlin', '地缚戒隶 地画戈兰林', '地縛戒隷 ジオグレムリン', 'Synchro Monster', 'Fiend', 'DARK', 6, 2000, 1000, '暗属性调整＋调整以外的怪兽1只以上 这个卡名的①②的效果1回合各能使用1次。 ①：自己·对方的主要阶段，以对方场上1只表侧表示怪兽为对象才能发动。对方从以下选1个，自己让那个效果适用。 ●作为对象的怪兽破坏。 ●自己基本分回复作为对象的怪兽的攻击力的数值。 ②：自己·对方的战斗阶段才能发动。自己的手卡·场上·墓地的怪兽作为融合素材除外，把1只「地缚」融合怪兽融合召唤。'),
(33202303, 'Earthbound Servant Geo Gremlina', '地缚戒隶 地画戈兰林那', '地縛戒隷 ジオグレムリーナ', 'Fusion Monster', 'Fiend', 'DARK', 6, 2000, 1000, '「地缚」怪兽＋暗属性怪兽 这个卡名的①②③的效果1回合各能使用1次。 ①：这张卡特殊召唤的场合才能发动。从卡组把1只「地缚」怪兽加入手卡。 ②：以自己场上1只暗属性同调怪兽为对象才能发动。这个回合，那只怪兽可以直接攻击。 ③：对方场上的怪兽被「地缚」卡的效果破坏的场合，以那1只破坏的怪兽为对象才能发动。给与对方那只怪兽的原本攻击力数值的伤害。'),
(44094981, 'Earthbound Servant Geo Gryphon', '地缚戒隶 地画格里芬', '地縛戒隷 ジオグリフォン', 'Synchro Monster', 'Fiend', 'DARK', 8, 2500, 1500, '暗属性调整＋调整以外的怪兽1只以上 这个卡名的①②的效果1回合各能使用1次。 ①：自己·对方回合可以发动。从自己墓地把「地缚戒隶 地画狮鹫」以外的1只「地缚」怪兽守备表示特殊召唤。这个回合，自己不是融合·同调怪兽不能从额外卡组特殊召唤。 ②：这张卡被对方破坏的场合才能发动。场上1张卡破坏。那之后，给与对方为自己的场上·墓地的「地缚」怪兽种类×300伤害。'),
(45716579, 'Earthbound Servant Geo Kraken', '地缚戒隶 地画克拉肯', '地縛戒隷 ジオクラーケン', 'Fusion Monster', 'Fiend', 'DARK', 8, 2800, 1200, '「地缚」怪兽×2 这个卡名的①②的效果1回合各能使用1次。 ①：这张卡特殊召唤的场合才能发动。从自己的卡组·墓地把1张场地魔法卡加入手卡。 ②：从对方的额外卡组有怪兽特殊召唤的场合才能发动。把这个回合特殊召唤的对方场上的怪兽全部破坏，给与对方破坏的怪兽数量×800伤害。'),
(67105242, 'Earthbound Spirit', '缚地灵', '地縛霊', 'Normal Monster', 'Fiend', 'EARTH', 4, 500, 2000, '战死沙场的士兵们的灵魂所聚集而产生的怨灵，踏入这片土地的人将被牵引入地底深处。'),
(29934351, 'Earthbound Wave', '地缚波', '地縛波', 'Trap Card', 'Counter', NULL, NULL, NULL, NULL, '自己场上有名字带有「地缚神」的怪兽表侧表示存在的场合才能发动。对方的魔法·陷阱卡的发动无效并破坏。'),
(96907086, 'Earthbound Whirlwind', '地缚旋风', '地縛旋風', 'Spell Card', 'Normal', NULL, NULL, NULL, NULL, '自己场上有名字带有「地缚神」的怪兽表侧表示存在的场合才能发动。对方场上存在的魔法·陷阱卡全部破坏。'),
(82828051, 'Earthquake', '地震', 'アースクエイク', 'Spell Card', 'Normal', NULL, NULL, NULL, NULL, '场上存在的表侧表示怪兽全部变成守备表示。'),
(61864793, 'Earthquake Giant', '地震巨人', 'アースクエイク・ジャイアント', 'Effect Monster', 'Rock', 'EARTH', 5, 1600, 2100, '这张卡的表示形式变更时，可以选择对方场上存在的1只怪兽，把表示形式变更。这个效果1回合只能使用1次。'),
(60866277, 'Earthshaker', '地壳变动', '地殻変動', 'Trap Card', 'Normal', NULL, NULL, NULL, NULL, '自己选择2个属性。对方从那之中选择1个。场上表侧表示存在的选择的属性的怪兽全部破坏。'),
(54407825, 'Earthshattering Event', '惊天动地', '驚天動地', 'Spell Card', 'Continuous', NULL, NULL, NULL, NULL, '①：从自己或者对方的卡组有卡被送去墓地的场合，以自己或者对方的墓地1张卡为对象把这个效果发动。那张卡回到持有者卡组。这个效果的发动后，直到回合结束时双方不能从卡组把卡送去墓地。'),
(63845230, 'Eater of Millions', '吞食百万的暴食兽', '百万喰らいのグラットン', 'Effect Monster', 'Fiend', 'DARK', 1, -1, -1, '这张卡不能通常召唤。从自己的手卡·场上·额外卡组把卡5张以上里侧表示除外的场合才能特殊召唤。 ①：这张卡的攻击力·守备力上升里侧表示除外中的卡数量×100。 ②：这张卡只要在怪兽区域存在，不能解放，也不能作为融合·同调·超量召唤的素材。 ③：1回合1次，这张卡和对方怪兽进行战斗的伤害步骤开始时才能发动。那只对方怪兽里侧表示除外。'),
(42578427, 'Eatgaboon', '捕鼠夹', 'ねずみ取り', 'Trap Card', 'Normal', NULL, NULL, NULL, NULL, '对方召唤·反转召唤的怪兽的攻击力在500以下的场合，可以把那1只怪兽破坏。'),
(94384774, 'Ebisu Shinsen Matsuri', '海老须神鲜祭', '海老須神鮮まつり', 'Trap Card', 'Continuous', NULL, NULL, NULL, NULL, '①：效果怪兽特殊召唤的场合，以那之内的1只为对象才能发动（同一连锁上最多1次）。在从那只怪兽的控制者来看的对方的场上把1只「神鲜衍生物」（水族·水·3星·攻/守0）守备表示特殊召唤。 ②：自己·对方的战斗阶段开始时才能发动1次。这张卡和场上的衍生物全部破坏，在自己场上把1只「海老须衍生物」（天使族·水·7星·攻/守?）特殊召唤。这衍生物的攻击力·守备力变成这个效果破坏的衍生物数量×700。'),
(88341502, 'Ebon Arrow', '黑翼箭矢', 'ブラック・アロー', 'Trap Card', 'Normal', NULL, NULL, NULL, NULL, '选择自己场上表侧表示存在的1只怪兽发动。直到结束阶段时，那只怪兽的攻击力下降500，攻击守备表示怪兽时，若攻击力超过那个守备力，给与对方基本分那个数值的战斗伤害。选择怪兽战斗破坏怪兽送去墓地时，给与对方基本分破坏怪兽的原本守备力数值的伤害。'),
(85551711, 'Ebon High Magician', '虚空的黑之魔导师', '虚空の黒魔導師', 'XYZ Monster', 'Spellcaster', 'DARK', 7, 2300, 2800, '魔法师族7星怪兽×2 ①：只要持有超量素材的这张卡在怪兽区域存在，自己在对方回合可以把速攻魔法卡以及陷阱卡从手卡发动。那个发动之际把这张卡1个超量素材取除。 ②：超量召唤的这张卡被对方的效果送去墓地的场合或者被战斗破坏送去墓地的场合才能发动。从手卡·卡组把1只魔法师族·暗属性怪兽特殊召唤。那之后，可以选场上1张卡破坏。'),
(96471335, 'Ebon Illusion Magician', '幻想黑之魔导师', '幻想の黒魔導師', 'XYZ Monster', 'Spellcaster', 'DARK', 7, 2500, 2100, '7星怪兽×2 这张卡也能在自己场上的6阶的魔法师族超量怪兽上面重叠来超量召唤。「幻想之黑魔导师」的②的效果1回合只能使用1次。 ①：1回合1次，把这张卡1个超量素材取除才能发动。从手卡·卡组把1只魔法师族的通常怪兽特殊召唤。 ②：魔法师族的通常怪兽的攻击宣言时，以对方场上1张卡为对象才能发动。那张卡除外。'),
(46128076, 'Ebon Magician Curran', '黑魔导师 库兰', '黒魔導師クラン', 'Effect Monster', 'Spellcaster', 'DARK', 2, 1200, NULL, '自己的准备阶段时，给与对方基本分对方场上存在的怪兽数×300分数值的伤害。'),
(96029570, 'Ebon Sun', '漆黑的太阳', '漆黒の太陽', 'Spell Card', 'Continuous', NULL, NULL, NULL, NULL, '这个卡名的①②③的效果1回合各能使用1次。 ①：自己场上的表侧表示怪兽被战斗·效果破坏的场合才能发动。自己基本分回复那些怪兽的原本攻击力合计的数值。 ②：从自己墓地有怪兽表侧表示特殊召唤的场合，以那之内的1只为对象才能发动。那只怪兽的攻击力上升1000。 ③：魔法·陷阱卡从自己手卡丢弃去自己墓地的场合，以那之内的1张为对象才能发动。那张卡加入手卡。'),
(16825874, 'Eccentric Boy', '古怪少年', 'エキセントリック・ボーイ', 'Tuner Monster', 'Spellcaster', 'WIND', 3, 800, 200, '把这张卡作为同调素材的场合，其他的同调素材怪兽必须是手卡1只怪兽。这张卡为同调素材的同调怪兽效果不能发动并无效化，从场上离开的场合从游戏中除外。'),
(78397661, 'Ecclesia and the Dark Dragon', '黑衣龙之艾克利西亚', '黒き竜のエクレシア', 'Synchro Monster', 'Spellcaster', 'LIGHT', 8, 2500, 2500, '调整＋调整以外的怪兽1只以上 这个卡名的①②的效果1回合各能使用1次。 ①：自己·对方的主要阶段才能发动。这张卡直到结束阶段除外，从自己的卡组·墓地把1只「阿不思的落胤」或者有那个卡名记述的4星以下的怪兽特殊召唤。 ②：这张卡在墓地存在的场合，以自己的墓地·除外状态的1只8星融合怪兽和场上1张卡为对象才能发动。那2张卡和这张卡回到卡组。'),
(38798785, 'Echelon of the Fire Kings', '炎王的结袭', '炎王の結襲', 'Trap Card', 'Normal', NULL, NULL, NULL, NULL, '这个卡名的①②的效果1回合各能使用1次。 ①：从自己的手卡·卡组·墓地各把1只兽族·兽战士族·鸟兽族的炎属性怪兽特殊召唤（相同种族最多1只）。这个效果特殊召唤的怪兽的效果无效化，结束阶段破坏。 ②：把墓地的这张卡除外才能发动。这个回合，在自己的「炎王」怪兽的召唤·特殊召唤成功时对方不能把魔法·陷阱·怪兽的效果发动。'),
(15582767, 'Echo Oscillation', '连成的振动', '連成する振動', 'Trap Card', 'Continuous', NULL, NULL, NULL, NULL, '「连成的振动」的效果1回合只能使用1次。 ①：以自己的灵摆区域1张卡为对象才能把这个效果发动。那张卡破坏，那之后，自己从卡组抽1张。'),
(45852939, 'Eclipse Twins', '蚀之双子', '蝕の双仔', 'XYZ Monster', 'Warrior', 'LIGHT', 4, 2500, 1200, '4星怪兽×2 这张卡超量召唤的场合，可以让自己场上的4阶怪兽作为4星怪兽来成为素材。这个卡名的②的效果1回合只能使用1次。 ①：把这张卡1个超量素材取除才能发动。这个回合，这张卡在同1次的战斗阶段中最多2次可以向怪兽攻击。 ②：这张卡被送去墓地的场合，以自己墓地2只其他的4阶以下的超量怪兽为对象才能发动。那2只之内的1只特殊召唤，另1只作为那只怪兽的超量素材。'),
(51858306, 'Eclipse Wyvern', '日蚀飞龙', 'エクリプス・ワイバーン', 'Effect Monster', 'Dragon', 'LIGHT', 4, 1600, 1000, '①：这张卡被送去墓地的场合发动。从卡组把1只光属性或者暗属性的龙族·7星以上的怪兽除外。 ②：墓地的这张卡被除外的场合才能发动。这张卡的①的效果除外的怪兽加入手卡。'),
(30350202, 'Eclipse, Dragon Ruler of Catastrophes', '凶征龙－日蚀', '凶征竜－エクレプシス', 'XYZ Monster', 'Dragon', 'DARK', 7, 2700, 1900, '龙族7星怪兽×2 这个卡名的①②的效果1回合各能使用1次。 ①：这张卡超量召唤的场合，以自己的墓地·除外状态的1只4星以下的「征龙」怪兽为对象才能发动。把1只在那只怪兽有卡名记述的7星或7阶的「征龙」怪兽从自己的卡组·除外状态特殊召唤。那之后，作为对象的怪兽回到卡组。 ②：对方把魔法·陷阱卡的效果发动时，把这张卡2个超量素材取除才能发动。那个发动无效并除外。'),
(4192696, 'Eco, Mystical Spirit of the Forest', '森之圣灵 木灵', '森の聖霊 エーコ', 'Effect Monster', 'Plant', 'EARTH', 4, 1700, 1000, '对方的卡的效果让自己受到伤害时才能发动。这张卡从手卡特殊召唤，给与对方基本分和受到的伤害相同的伤害。并且，再让这个回合双方受到的效果伤害变成0。'),
(60514625, 'Ecole de Zone', '忘我画派', 'エコール・ド・ゾーン', 'Spell Card', 'Field', NULL, NULL, NULL, NULL, '这个卡名的①的效果1回合只能使用1次。 ①：回合玩家只对怪兽1只的召唤·反转召唤·特殊召唤成功的场合发动。那只怪兽破坏，那个控制者在那个自身场上把1只「假面衍生物」（魔法师族·暗·1星·攻/守?）特殊召唤。这衍生物攻击力·守备力变成和这个效果破坏的怪兽的各自数值相同，不能直接攻击。 ②：表侧表示的这张卡从场上离开的场合场上的「假面衍生物」全部破坏。'),
(97342942, 'Ectoplasmer', '通灵外质体', 'エクトプラズマー', 'Spell Card', 'Continuous', NULL, NULL, NULL, NULL, '双方玩家各自在自己的结束阶段时只有1次，选自己场上表侧表示存在的1只怪兽，把那只怪兽解放，给与对方基本分解放的那只怪兽的原本攻击力一半数值的伤害。'),
(300101001, 'Ectoplasmic Fortification!', NULL, NULL, 'Skill Card', 'Bonz', NULL, NULL, NULL, NULL, NULL),
(96352326, 'Eda the Sun Magician', '太阳之魔术师 埃达', '太陽の魔術師エダ', 'Effect Monster', 'Spellcaster', 'EARTH', 4, 1500, 1500, '这个卡名的①②的效果1回合各能使用1次。 ①：这张卡召唤·反转的场合才能发动。从手卡·卡组把「太阳之魔术师 埃达」以外的1只守备力1500的魔法师族怪兽里侧守备表示特殊召唤。 ②：对方主要阶段才能发动。选自己场上1只里侧表示的魔法师族怪兽变成表侧攻击表示或者表侧守备表示。'),
(95457011, 'Edea the Heavenly Squire', '天帝从骑埃迪亚', '天帝従騎イデア', 'Effect Monster', 'Warrior', 'LIGHT', 1, 800, 1000, '这个卡名的①②的效果1回合各能使用1次。 ①：这张卡召唤·特殊召唤的场合才能发动。从卡组把「天帝从骑 爱迪娅」以外的1只攻击力800/守备力1000的怪兽守备表示特殊召唤。这个效果的发动后，直到回合结束时自己不能从额外卡组把怪兽特殊召唤。 ②：这张卡被送去墓地的场合，以自己的除外状态的1张「帝王」魔法·陷阱卡为对象才能发动。那张卡加入手卡。'),
(84361420, 'Edge Hammer', '金刃锤击', 'エッジ・ハンマー', 'Trap Card', 'Normal', NULL, NULL, NULL, NULL, '把自己场上存在的1只「元素英雄 金刃侠」作为祭品。对方场上存在的1只怪兽破坏，给与对方基本分那只怪兽的原本攻击力数值的伤害。'),
(61173621, 'Edge Imp Chain', '锋利小鬼・锁链', 'エッジインプ・チェーン', 'Effect Monster', 'Fiend', 'DARK', 4, 1200, 1800, '这个卡名的①②的效果1回合只能有1次使用其中任意1个。 ①：这张卡的攻击宣言时才能发动。从卡组把1只「锋利小鬼·链子」加入手卡。 ②：这张卡从手卡·场上送去墓地的场合才能发动。从卡组把1张「魔玩具」卡加入手卡。'),
(73240432, 'Edge Imp Cotton Eater', '锋利小鬼・棉花吞噬者', 'エッジインプ・コットン・イーター', 'Pendulum Effect Monster', 'Fiend', 'DARK', 7, 2400, 1600, '「锋利小鬼·棉花吞噬者」的怪兽效果1回合只能使用1次。 ①：这张卡特殊召唤成功的场合才能发动。给与对方为自己墓地的「魔玩具」怪兽数量×200伤害。'),
(34566435, 'Edge Imp Frightfuloid', '锋利小鬼·仿DT', 'エッジインプ・DTモドキ', 'Effect Monster', 'Fiend', 'DARK', 4, 1300, 1300, '这张卡在规则上也当作「魔玩具」卡使用。「锋利小鬼·仿DT」的效果1回合只能使用1次。 ①：以自己的场上·墓地1只「魔玩具」融合怪兽为对象才能发动。这张卡的攻击力·守备力直到回合结束时变成和那只怪兽的原本数值相同。'),
(30068120, 'Edge Imp Sabres', '锋利小鬼・剪刀', 'エッジインプ・シザー', 'Effect Monster', 'Fiend', 'DARK', 3, 1200, 800, '「锋利小鬼·剪刀」的效果1回合只能使用1次。 ①：这张卡在墓地存在的场合，让1张手卡回到卡组最上面才能发动。这张卡从墓地守备表示特殊召唤。'),
(34688023, 'Edge Imp Saw', '锋利小鬼·锯子', 'エッジインプ・ソウ', 'Effect Monster', 'Fiend', 'DARK', 3, 500, 1000, '「锋利小鬼·锯子」的效果1回合只能使用1次。 ①：这张卡召唤成功时，把手卡1只「毛绒动物」怪兽送去墓地才能发动。自己从卡组抽2张，那之后，选1张手卡回到卡组最上面或者最下面。'),
(29280589, 'Edge Imp Scythe', '锋利小鬼・镰刀', 'エッジインプ・サイズ', 'Effect Monster', 'Fiend', 'DARK', 3, 1000, NULL, '这个卡名的①②的效果1回合各能使用1次。 ①：对方主要阶段，把手卡的这张卡给对方观看才能发动。从自己的手卡·场上把「魔玩具」融合怪兽卡决定的包含手卡的这张卡的融合素材怪兽送去墓地，把那1只融合怪兽从额外卡组融合召唤。 ②：自己场上的「魔玩具」融合怪兽被战斗·效果破坏的场合，可以作为代替把墓地的这张卡除外。'),
(97567736, 'Edge Imp Tomahawk', '锋利小鬼·战斧', 'エッジインプ・トマホーク', 'Effect Monster', 'Fiend', 'DARK', 4, 1800, 800, '「锋利小鬼·战斧」的①②的效果1回合各能使用1次。 ①：把手卡1只「锋利小鬼」怪兽送去墓地才能发动。给与对方800伤害。 ②：从卡组把「锋利小鬼·战斧」以外的1只「锋利小鬼」怪兽送去墓地才能发动。直到结束阶段，这张卡当作和送去墓地的怪兽同名卡使用。'),
(85636437, 'Edge of the Ring', '土俵间际', '土俵間際', 'Spell Card', 'Quick-Play', NULL, NULL, NULL, NULL, '①：自己基本分比对方少的场合，以对方场上1只表侧表示怪兽为对象才能发动。给与对方那只怪兽的原本攻击力一半数值的伤害。这张卡的发动后，直到回合结束时对方受到的全部伤害变成0。'),
(97268402, 'Effect Veiler', '效果遮蒙者', 'エフェクト・ヴェーラー', 'Tuner Monster', 'Spellcaster', 'LIGHT', 1, NULL, NULL, '①：对方主要阶段，把这张卡从手卡送去墓地，以对方场上1只效果怪兽为对象才能发动。那只对方怪兽的效果直到回合结束时无效。'),
(73178098, 'Ego Boost', '虚荣巨影', '虚栄巨影', 'Spell Card', 'Quick-Play', NULL, NULL, NULL, NULL, '①：怪兽的攻击宣言时，以场上1只表侧表示怪兽为对象才能发动。那只怪兽的攻击力直到那次战斗阶段结束时上升1000。'),
(96914272, 'Egotistical Ape', '虚荣的大猿', '虚栄の大猿', 'Tuner Monster', 'Beast', 'EARTH', 5, 1200, 1200, '这张卡不能通常召唤。从手卡把1只兽族怪兽送去墓地的场合可以特殊召唤。这个方法特殊召唤成功时，可以把送去墓地的那只兽族怪兽的等级确认，从下面效果选择1个发动。 ●这张卡的等级上升那个等级数值。 ●这张卡的等级下降那个等级数值。'),
(42166000, 'Egyptian God Slime', '神・史莱姆', '神・スライム', 'Fusion Monster', 'Aqua', 'WATER', 10, 3000, 3000, '水族怪兽＋水属性·10星怪兽 这张卡用融合召唤以及以下方法才能从额外卡组特殊召唤。 ●把自己场上1只攻击力0的水族·10星怪兽解放的场合可以从额外卡组特殊召唤。 ①：需要怪兽3只解放的怪兽上级召唤的场合，这张卡可以作为3只的数量解放。 ②：这张卡不会被战斗破坏，对方不能选择「神·史莱姆」以外的自己场上的怪兽作为攻击对象，也不能作为效果的对象。'),
(44178886, 'Ehren, Lightsworn Monk', '光道武僧 爱琳', 'ライトロード・モンク エイリン', 'Effect Monster', 'Warrior', 'LIGHT', 4, 1600, 1000, '①：这张卡向守备表示怪兽攻击的伤害计算前发动。那只怪兽回到持有者卡组。 ②：自己结束阶段发动。从自己卡组上面把3张卡送去墓地。'),
(96570609, 'Ehther the Heavenly Monarch', '天帝埃忒耳', '天帝アイテール', 'Effect Monster', 'Fairy', 'LIGHT', 8, 2800, 1000, '这张卡可以把1只上级召唤的怪兽解放作上级召唤。 ①：这张卡上级召唤的场合才能发动。从手卡·卡组把「帝王」魔法·陷阱卡2种类各1张送去墓地，从卡组把1只攻击力2400以上而守备力1000的怪兽特殊召唤。这个效果特殊召唤的怪兽在结束阶段回到手卡。 ②：这张卡在手卡存在的场合，对方主要阶段，从自己墓地把1张「帝王」魔法·陷阱卡除外才能发动（同一连锁上最多1次）。进行这张卡的上级召唤。'),
(31596518, 'Eidos the Underworld Monarch', '冥帝王厄多斯', '冥帝王エイドス', 'Effect Monster', 'Spellcaster', 'DARK', 6, 2400, 1000, '这个卡名的①②③的效果1回合各能使用1次。 ①：这张卡召唤·特殊召唤的场合才能发动。从自己的卡组·墓地把1张「帝王」魔法·陷阱卡或者1只攻击力2800/守备力1000的怪兽加入手卡。 ②：宣言1个属性才能发动。场上1只怪兽的属性变成宣言的属性。 ③：这张卡在墓地存在的状态，自己把攻击力2400以上而守备力1000的怪兽上级召唤的场合才能发动。这张卡加入手卡或特殊召唤。'),
(59463312, 'Eidos the Underworld Squire', '冥帝从骑厄多斯', '冥帝従騎エイドス', 'Effect Monster', 'Spellcaster', 'DARK', 2, 800, 1000, '这个卡名的②的效果1回合只能使用1次。 ①：这张卡召唤·特殊召唤的场合发动。这个回合，自己在通常召唤外加上只有1次，自己主要阶段可以上级召唤。 ②：把墓地的这张卡除外，以「冥帝从骑 哀多斯」以外的自己墓地1只攻击力800/守备力1000的怪兽为对象才能发动。那只怪兽守备表示特殊召唤。这个效果的发动后，直到回合结束时自己不能从额外卡组把怪兽特殊召唤。'),
(40844553, 'Einherjar Token', '极星天 女武神', '極星天ヴァルキュリア', 'Token', 'Warrior', NULL, NULL, NULL, NULL, NULL),
(88039509, 'Einroid', '一型机人', 'アイン・ロイド', 'Effect Monster', 'Machine', 'EARTH', 1, 200, 1800, '这个卡名的效果1回合只能使用1次。 ①：这张卡被战斗·效果破坏的场合才能发动。从卡组把2只4星以下的机械族怪兽送去墓地。'),
(54059040, 'Eisbahn', '滑冰场', 'アイスバーン', 'Trap Card', 'Continuous', NULL, NULL, NULL, NULL, '自己场上有水属性怪兽表侧表示存在，水属性以外的怪兽召唤·特殊召唤成功时，那些怪兽变成守备表示。'),
(35283277, 'Eka the Flame Buddy', '炎兽使 埃卡', '炎獣使いエーカ', 'Effect Monster', 'Warrior', 'FIRE', 4, 1500, 200, '这个卡名的①②的效果1回合各能使用1次。 ①：这张卡召唤·特殊召唤成功的场合，以自己或者对方的魔法与陷阱区域1张表侧表示的怪兽卡为对象才能发动。那张卡在自己场上特殊召唤。 ②：以这张卡以外的自己场上1只表侧表示怪兽为对象才能发动。那只表侧表示怪兽当作攻击力上升500的装备卡使用给这张卡装备。'),
(69954399, 'Ekibyo Drakmord', '疫病病毒 黑尘', '疫病ウィルス ブラックダスト', 'Spell Card', 'Equip', NULL, NULL, NULL, NULL, '装备这张卡的怪兽不能攻击。装备怪兽的控制者的第2次回合结束时，装备怪兽破坏。这个效果成功的场合，这张卡回到持有者的手卡。'),
(29570824, 'Ekto Enneacraft - "tromarIA"', '纠罪巧ϝ’－恐怖“tromarIA”', '糾罪巧ϝ’－「tromarIA」', 'Pendulum Flip Effect Monster', 'Machine', 'EARTH', 1, 100, 1000, '①：把手卡的这张卡给对方观看才能发动（这个效果发动的回合，自己不用里侧守备表示不能把怪兽特殊召唤）。从手卡把1只怪兽里侧守备表示特殊召唤。 ②：包含把怪兽特殊召唤效果的卡的效果由对方发动时，把里侧表示的这张卡变成表侧守备表示才能发动。从卡组把1张「纠罪巧」卡加入手卡。 ③：这张卡反转的场合发动。对方场上1只效果怪兽的效果直到回合结束时无效。'),
(92379223, 'El Dorado Adelantado', '黄金征服王', '黄金の征服王', 'Trap Card', 'Normal', NULL, NULL, NULL, NULL, '这个卡名的卡在1回合只能发动1张。 ①：自己场上有「黄金国巫妖」怪兽存在的场合，可以从以下效果选择1个发动。 ●选除外的自己的「黄金国永生药」魔法·陷阱卡3种类各1张回到卡组，场上的卡全部破坏。 ●选除外的自己的「黄金乡」魔法·陷阱卡3种类各1张回到卡组，对方基本分变成一半。那之后，自己基本分回复对方基本分的数值。'),
(19261966, 'El Shaddoll Anoyatyllis', '神影依・异花莉莉丝', 'エルシャドール・アノマリリス', 'Fusion Monster', 'Fiend', 'WATER', 9, 2700, 2000, '「影依」怪兽＋水属性怪兽 这张卡用融合召唤才能从额外卡组特殊召唤。 ①：只要这张卡在怪兽区域存在，双方不能用魔法·陷阱卡的效果从手卡·墓地把怪兽特殊召唤。 ②：这张卡被送去墓地的场合，以自己墓地1张「影依」魔法·陷阱卡为对象才能发动。那张卡加入手卡。'),
(50907446, 'El Shaddoll Apkallone', '神影依・阿普卡鳌魔', 'エルシャドール・アプカローネ', 'Fusion Monster', 'Spellcaster', 'DARK', 6, 2500, 2000, '属性不同的「影依」怪兽×2 这张卡用融合召唤才能从额外卡组特殊召唤。这个卡名的①③的效果1回合各能使用1次。 ①：这张卡特殊召唤的场合，以场上1张表侧表示卡为对象才能发动。那张卡的效果无效。 ②：这张卡不会被战斗破坏。 ③：这张卡被送去墓地的场合才能发动。从自己的卡组·墓地把1张「影依」卡加入手卡。那之后，选自己1张手卡丢弃。'),
(20366274, 'El Shaddoll Construct', '神影依・拿非利', 'エルシャドール・ネフィリム', 'Fusion Monster', 'Fairy', 'LIGHT', 8, 2800, 2500, '「影依」怪兽＋光属性怪兽 这张卡用融合召唤才能从额外卡组特殊召唤。 ①：这张卡特殊召唤的场合才能发动。从卡组把1张「影依」卡送去墓地。 ②：这张卡和特殊召唤的怪兽进行战斗的伤害步骤开始时发动。那只怪兽破坏。 ③：这张卡被送去墓地的场合，以自己墓地1张「影依」魔法·陷阱卡为对象才能发动。那张卡加入手卡。'),
(6417578, 'El Shaddoll Fusion', '神影依结合', '神の写し身との接触', 'Spell Card', 'Quick-Play', NULL, NULL, NULL, NULL, '这个卡名的卡在1回合只能发动1张。 ①：自己的手卡·场上的怪兽作为融合素材，把1只「影依」融合怪兽融合召唤。'),
(48424886, 'El Shaddoll Grysta', '神影依・古利水晶', 'エルシャドール・エグリスタ', 'Fusion Monster', 'Rock', 'FIRE', 7, 2450, 1950, '「影依」怪兽＋炎属性怪兽 这张卡用融合召唤才能从额外卡组特殊召唤。这个卡名的①的效果1回合只能使用1次。 ①：对方把怪兽特殊召唤之际才能发动。那次特殊召唤无效，那些怪兽破坏。那之后，从自己手卡选1张「影依」卡送去墓地。 ②：这张卡被送去墓地的场合，以自己墓地1张「影依」魔法·陷阱卡为对象才能发动。那张卡加入手卡。'),
(32467459, 'El Shaddoll Meshahrail', '神影依・弥赛芙蕾尔', 'エルシャドール・メシャフレール', 'Fusion Monster', 'Machine', 'EARTH', 10, 2800, 1000, '「影依」怪兽＋暗属性怪兽＋地属性怪兽 这张卡不用融合召唤不能特殊召唤。 ①：场上的这张卡不受对方发动的魔法·陷阱卡的效果影响，也不受原本的等级·阶级的数值比这张卡的等级低的对方怪兽发动的效果影响。 ②：1回合1次，支付800基本分才能发动。从卡组把1张「影依」卡或「炼狱」魔法·陷阱卡加入手卡。 ③：这张卡被送去墓地的场合才能发动。从自己墓地把1只「影依」怪兽特殊召唤。'),
(74822425, 'El Shaddoll Shekhinaga', '神影依・舍金那迦', 'エルシャドール・シェキナーガ', 'Fusion Monster', 'Machine', 'EARTH', 10, 2600, 3000, '「影依」怪兽＋地属性怪兽 这张卡用融合召唤才能从额外卡组特殊召唤。这个卡名的①的效果1回合只能使用1次。 ①：特殊召唤的怪兽的效果发动时才能发动。那个发动无效并破坏。那之后，从自己手卡选1张「影依」卡送去墓地。 ②：这张卡被送去墓地的场合，以自己墓地1张「影依」魔法·陷阱卡为对象才能发动。那张卡加入手卡。'),
(74009824, 'El Shaddoll Wendigo', '神影依・温蒂戈', 'エルシャドール・ウェンディゴ', 'Fusion Monster', 'Psychic', 'WIND', 6, 200, 2800, '「影依」怪兽＋风属性怪兽 这张卡用融合召唤才能从额外卡组特殊召唤。这个卡名的①的效果1回合只能使用1次。 ①：以自己场上1只怪兽为对象才能发动。这个回合，那只怪兽不会被和特殊召唤的对方怪兽的战斗破坏。这个效果在对方回合也能发动。 ②：这张卡被送去墓地的场合，以自己墓地1张「影依」魔法·陷阱卡为对象才能发动。那张卡加入手卡。'),
(94977269, 'El Shaddoll Winda', '神影依・米德拉什', 'エルシャドール・ミドラーシュ', 'Fusion Monster', 'Spellcaster', 'DARK', 5, 2200, 800, '「影依」怪兽＋暗属性怪兽 这张卡用融合召唤才能从额外卡组特殊召唤。 ①：场上的这张卡不会被对方的效果破坏。 ②：只要这张卡在怪兽区域存在，那个期间双方1回合只能有1次把怪兽特殊召唤。 ③：这张卡被送去墓地的场合，以自己墓地1张「影依」魔法·陷阱卡为对象才能发动。那张卡加入手卡。'),
(92223430, 'Elborz, the Sacred Lands of Simorgh', '西摩格之灵峰 厄尔布鲁士', '神鳥の霊峰エルブルズ', 'Spell Card', 'Field', NULL, NULL, NULL, NULL, '这个卡名的②③的效果1回合各能使用1次。 ①：场上的鸟兽族·风属性怪兽的攻击力·守备力上升300。 ②：把手卡的5星以上的鸟兽族·风属性怪兽给对方观看才能发动。这个回合，自己可以把鸟兽族怪兽召唤的场合需要的解放减少1只。 ③：自己场上有鸟兽族·风属性怪兽存在的场合才能发动。把1只鸟兽族怪兽召唤。'),
(6367785, 'Eldeen', '艾尔丁', 'エルディーン', 'Normal Monster', 'Spellcaster', 'LIGHT', 3, 950, 1000, '用手中的杖，使出各种魔法攻击。'),
(80532587, 'Elder Entity N''tss', '旧神努茨', '旧神ヌトス', 'Fusion Monster', 'Fairy', 'LIGHT', 4, 2500, 1200, '同调怪兽＋超量怪兽 把自己场上的上记的卡送去墓地的场合才能特殊召唤。自己对「旧神 努茨」1回合只能有1次特殊召唤。 ①：1回合1次，自己主要阶段才能发动。从手卡把1只4星怪兽特殊召唤。 ②：这张卡被送去墓地的场合，以场上1张卡为对象才能发动。那张卡破坏。'),
(17412721, 'Elder Entity Norden', '旧神 诺登', '旧神ノーデン', 'Fusion Monster', 'Fairy', 'WATER', 4, 2000, 2200, '同调怪兽或超量怪兽＋同调怪兽或超量怪兽 ①：这张卡特殊召唤成功时，以自己墓地1只4星以下的怪兽为对象才能发动。那只怪兽效果无效特殊召唤。这张卡从场上离开时那只怪兽除外。'),
(61737116, 'Elder of the Six Samurai', '六武众之隐居士', '六武衆のご隠居', 'Effect Monster', 'Warrior', 'EARTH', 3, 400, NULL, '对方场上有怪兽存在，自己场上没有怪兽存在的场合，这张卡可以从手卡特殊召唤。'),
(95440946, 'Eldlich the Golden Lord', '黄金卿埃尔德里奇', '黄金卿エルドリッチ', 'Effect Monster', 'Zombie', 'LIGHT', 10, 2500, 2800, '这个卡名的①②的效果1回合各能使用1次。 ①：从手卡把这张卡和1张魔法·陷阱卡送去墓地，以场上1张卡为对象才能发动。那张卡送去墓地。 ②：这张卡在墓地存在的场合，把自己场上1张魔法·陷阱卡送去墓地才能发动。这张卡加入手卡。那之后，可以从手卡把1只不死族怪兽特殊召唤。这个效果特殊召唤的怪兽直到对方回合结束时攻击力·守备力上升1000，不会被效果破坏。'),
(74889525, 'Eldlich the Mad Golden Lord', '征服王・黄金狂埃尔德里奇', '黄金狂エルドリッチ', 'Fusion Monster', 'Zombie', 'LIGHT', 10, 3800, 3500, '「黄金国巫妖」怪兽＋5星以上的不死族怪兽 这个卡名的③的效果1回合只能使用1次。 ①：这张卡只要在怪兽区域存在，卡名当作「黄金卿 黄金国巫妖」使用。 ②：场上的这张卡不会被战斗·效果破坏。 ③：把自己场上1只不死族怪兽解放，以对方场上1只表侧表示怪兽为对象才能发动。得到那只怪兽的控制权。那只怪兽直到回合结束时不能攻击，不能把效果发动。'),
(68829754, 'Eldlixir of Black Awakening', '黑色觉醒的埃尔德里希尔', '黒き覚醒のエルドリクシル', 'Spell Card', 'Normal', NULL, NULL, NULL, NULL, '这个卡名的①②的效果1回合只能有1次使用其中任意1个。 ①：从手卡·卡组把1只不死族怪兽守备表示特殊召唤。自己场上没有「黄金国巫妖」怪兽存在的场合，这个效果不是「黄金国巫妖」怪兽不能特殊召唤。这张卡的发动后，直到回合结束时自己不是不死族怪兽不能特殊召唤。 ②：把墓地的这张卡除外才能发动。从卡组把1张「黄金乡」魔法·陷阱卡在自己场上盖放。'),
(20612097, 'Eldlixir of Scarlet Sanguine', '红色血染的埃尔德里希尔', '紅き血染めのエルドリクシル', 'Trap Card', 'Normal', NULL, NULL, NULL, NULL, '这个卡名的①②的效果1回合只能有1次使用其中任意1个。 ①：从自己的卡组·墓地把1只不死族怪兽特殊召唤。自己场上没有「黄金国巫妖」怪兽存在的场合，这个效果不是「黄金国巫妖」怪兽不能特殊召唤。这张卡的发动后，直到回合结束时自己不是不死族怪兽不能特殊召唤。 ②：把墓地的这张卡除外才能发动。从卡组把1张「黄金乡」魔法·陷阱卡在自己场上盖放。'),
(22669793, 'Eldlixir of the Glorious Golden Land', '高贵黄金乡的埃尔德里希尔', '貴き黄金郷のエルドリクシル', 'Trap Card', 'Continuous', NULL, NULL, NULL, NULL, '这个卡名的①的效果1回合只能使用1次。 ①：可以支付800基本分，从以下效果选择1个发动。 ●这张卡变成通常怪兽（不死族·光·10星·攻1500/守2800）在怪兽区域特殊召唤（也当作陷阱卡使用）。自己场上有「黄金卿 黄金国巫妖」存在的场合，可以再让场上1只怪兽回到手卡。 ●自己的除外状态的1张「黄金乡」魔法·陷阱卡或「黄金国永生药」魔法·陷阱卡在自己场上盖放。'),
(94224458, 'Eldlixir of White Destiny', '白色宿命的埃尔德里希尔', '白き宿命のエルドリクシル', 'Spell Card', 'Quick-Play', NULL, NULL, NULL, NULL, '这个卡名的①②的效果1回合只能有1次使用其中任意1个。 ①：从自己的手卡·墓地把1只不死族怪兽特殊召唤。自己场上没有「黄金国巫妖」怪兽存在的场合，这个效果不是「黄金国巫妖」怪兽不能特殊召唤。这张卡的发动后，直到回合结束时自己不是不死族怪兽不能特殊召唤。 ②：自己主要阶段把墓地的这张卡除外才能发动。从卡组把1张「黄金乡」魔法·陷阱卡在自己场上盖放。'),
(95824983, 'Electric Jellyfish', '电气水母', '電気海月－フィサリア－', 'Effect Monster', 'Aqua', 'WATER', 4, 1400, 1700, '这个卡名的①②的效果1回合各能使用1次。 ①：从手卡·卡组以及自己场上的表侧表示的卡之中把1张「海」送去墓地才能发动。从手卡把1只水属性怪兽特殊召唤。 ②：场上有「海」存在，对方把魔法·怪兽的效果发动时才能发动。那个效果无效。那之后，可以让这张卡的攻击力·守备力上升600。'),
(55875323, 'Electric Lizard', '电蜥蜴', 'でんきトカゲ', 'Effect Monster', 'Thunder', 'EARTH', 3, 850, 800, '不死族以外的怪兽攻击这张卡的场合，那只怪兽下一个回合不能攻击宣言。'),
(11324436, 'Electric Snake', '电蛇', 'エレクトリック・スネーク', 'Effect Monster', 'Thunder', 'LIGHT', 3, 800, 900, '这张卡被对方的卡的效果从手卡丢弃去墓地时，从自己卡组抽2张卡。'),
(24725825, 'Electric Virus', '电虫', 'エレクトリック・ワーム', 'Effect Monster', 'Thunder', 'LIGHT', 3, 1000, 1000, '①：把这张卡从手卡丢弃去墓地，以对方场上1只龙族·机械族怪兽为对象才能发动。那只龙族·机械族怪兽的控制权直到结束阶段得到。'),
(9107531, 'Electro Blaster', '电力炮手', 'エレクトロ・ガンナー', 'Effect Monster', 'Machine', 'FIRE', 4, 1800, 1400, '这个卡名的①的效果1回合只能使用1次。 ①：自己把炎属性怪兽召唤·特殊召唤的场合才能发动。这张卡从手卡特殊召唤。那之后，可以从卡组把1只炎族·8星怪兽送去墓地。 ②：1回合1次，魔法卡发动的场合才能发动。自己场上的全部炎属性怪兽的攻击力上升300。'),
(37820550, 'Electro-Whip', '电击鞭', '電撃鞭', 'Spell Card', 'Equip', NULL, NULL, NULL, NULL, '雷族才能装备。1只装备怪兽的攻击力·守备力上升300。'),
(58680635, 'Electrode Beast Anion', '电极兽 阴离子', '電極獣アニオン', 'Effect Monster', 'Thunder', 'LIGHT', 2, 300, 100, '这个卡名的①②的效果1回合各能使用1次。 ①：这张卡召唤的场合才能发动。这张卡的等级变成4星。那之后，可以从自己的卡组·墓地把1张「灵魂变换装置」加入手卡。 ②：以自己场上1张其他卡为对象才能发动。那张卡和这张卡送去墓地，自己抽1张。'),
(21291696, 'Electrode Beast Cation', '电极兽 阳离子', '電極獣カチオン', 'Effect Monster', 'Thunder', 'LIGHT', 2, 300, 100, '这个卡名的①②的效果1回合各能使用1次。 ①：这张卡召唤的场合才能发动。从自己的卡组·墓地把1只「电极兽 阴离子」加入手卡。那之后，可以进行1只4星以下的雷族怪兽的召唤。这个效果的发动后，直到回合结束时自己不是光属性超量怪兽不能从额外卡组特殊召唤。 ②：以自己场上1只其他的雷族怪兽为对象才能发动。这张卡的等级直到回合结束时变成和那只怪兽的等级相同。'),
(7914843, 'Electromagnetic Bagworm', '电磁蓑衣虫', '電磁ミノ虫', 'Flip Effect Monster', 'Insect', 'LIGHT', 3, 200, 1400, '①：这张卡反转的场合，以对方场上1只机械族怪兽为对象发动。直到下次的自己结束阶段，得到那只机械族怪兽的控制权。 ②：这张卡被和怪兽的战斗破坏的场合发动。那只怪兽的攻击力·守备力下降500。'),
(91107093, 'Electromagnetic Shield', '电磁盾', '電磁シールド', 'Spell Card', 'Continuous', NULL, NULL, NULL, NULL, '自己场上表侧守备表示存在的3星以下的雷族怪兽不会被战斗破坏。自己场上有怪兽表侧攻击表示存在的场合，这张卡破坏。'),
(34710660, 'Electromagnetic Turtle', '超电磁乌龟', '超電磁タートル', 'Effect Monster', 'Machine', 'LIGHT', 4, NULL, 1800, '这个卡名的效果在决斗中只能使用1次。 ①：对方战斗阶段把墓地的这张卡除外才能发动。那次战斗阶段结束。'),
(90219263, 'Elegant Egotist', '万华镜－华丽的分身－', '万華鏡－華麗なる分身－', 'Spell Card', 'Normal', NULL, NULL, NULL, NULL, '①：场上有「鹰身女郎」存在的场合才能发动。从手卡·卡组把1只「鹰身女郎」或「鹰身女郎三姐妹」特殊召唤。'),
(79514956, 'Elegy the Melodious Diva', '幻奏音女 埃蕾姬', '幻奏の音女エレジー', 'Effect Monster', 'Fairy', 'LIGHT', 5, 2000, 1200, '①：只要这张卡在怪兽区域存在，自己场上的特殊召唤的「幻奏」怪兽不会被效果破坏。 ②：只要特殊召唤的这张卡在怪兽区域存在，自己场上的天使族怪兽的攻击力上升300。'),
(23118924, 'Element Doom', '元素恶魔', 'エレメント・デビル', 'Effect Monster', 'Fiend', 'DARK', 4, 1500, 1200, '这只怪兽在场上有特定的属性的怪兽存在的场合，得到以下的效果。 ●地属性：这张卡战斗破坏的效果怪兽的效果无效化。 ●风属性：这张卡战斗破坏对方怪兽的场合，只有1次可以再度攻击。'),
(30314994, 'Element Dragon', '元素龙', 'エレメント・ドラゴン', 'Effect Monster', 'Dragon', 'LIGHT', 4, 1500, 1200, '①：场上的怪兽属性让这张卡得到以下效果。 ●炎属性：这张卡的攻击力上升500。 ●风属性：这张卡战斗破坏对方怪兽时才能发动。这张卡只再1次可以继续攻击。');